    ["Edited"] = "Змінено",
    ["Everyday people"] = "Звичайні люди",
    ["Everyday people do not keep memories of your talks."] = "Звичайні люди не зберігають спогадів про твої розмови.",
    ["Everything together is too long. Shorten something so it stays under {max} characters."] = "Разом це занадто довго. Скороти щось, щоб усе вкладалося в {max} символів.",
    ["Example lines"] = "Приклади реплік",
    ["Facts the character noticed while you talked. Change or delete the ones that are wrong."] = "Факти, які персонаж помітив під час твоїх розмов. Зміни або видали неправильні.",
    ["For example: V has a sister called Lena."] = "Наприклад: у V є сестра на ім’я Лена.",
    ["Go back to the shipped text for {name}? All your changes to this character are removed."] = "Повернути вихідний текст для {name}? Усі твої зміни для цього персонажа буде видалено.",
    ["Go back to the shipped text for {name}? Your changes to this part are removed."] = "Повернути вихідний текст для {name}? Твої зміни в цій частині буде видалено.",
    ["How they sound: pace, attitude, favourite habits of speech."] = "Як вони говорять: темп, ставлення, улюблені мовні звички.",
    ["Lines in their voice. They show the tone only and are never said back word for word."] = "Репліки в їхній манері. Вони показують лише тон і ніколи не повторюються дослівно.",
    ["No match."] = "Нічого не знайдено.",
    ["Nothing yet."] = "Поки порожньо.",
    ["Opening the editor in your browser. Switch to your browser if it does not come to the front."] = "Редактор відкривається у браузері. Якщо вікно не з’явилося, перейди до браузера.",
    ["Parts of the character"] = "Частини персонажа",
    ["Picked up in your talks"] = "Дізналися з твоїх розмов",
    ["Reset everything"] = "Скинути все",
    ["Reset to default"] = "Скинути до стандартного",
    ["Save"] = "Зберегти",
    ["Saved."] = "Збережено.",
    ["Search characters"] = "Пошук персонажів",
    ["Short facts you write yourself, such as a name or a promise. The character knows them in every talk."] = "Короткі факти, які ти пишеш сам, наприклад ім’я чи обіцянку. Персонаж знає їх у кожній розмові.",
    ["Short rules this character always follows when talking, for example: Never swear. Answer in one sentence."] = "Короткі правила, яких персонаж завжди дотримується в розмові, наприклад: Не лайся. Відповідай одним реченням.",
    ["Short summary of earlier talks"] = "Короткий підсумок попередніх розмов",
    ["Speaking rules"] = "Правила мовлення",
    ["Speaking style"] = "Манера мовлення",
    ["Story characters"] = "Персонажі сюжету",
    ["That character was not found."] = "Цього персонажа не знайдено.",
    ["The Local AI pack finds these. It is not installed or not ready, so none are collected now."] = "Пакет Local AI знаходить їх. Він не встановлений або не готовий, тому зараз нічого не збирається.",
    ["The bio is too long. Keep it under {max} characters."] = "Біографія занадто довга. Тримай її коротшою за {max} символів.",
    ["The bio is too short. Use at least {max} characters."] = "Біографія занадто коротка. Напиши щонайменше {max} символів.",
    ["The conversation service is not running, so the editor cannot open. Restart the game."] = "Служба розмов не запущена, тому редактор не може відкритися. Перезапусти гру.",
    ["The editor could not be opened. Try again."] = "Не вдалося відкрити редактор. Спробуй ще раз.",
    ["The editor is closed. You can close this tab."] = "Редактор закрито. Цю вкладку можна закрити.",
    ["World rules"] = "Правила світу",
    ["Rules for the whole world, used for every character in every talk: face to face, phone and group chats. Write facts and style, for example how people talk or what nobody knows. They never replace the mod’s own rules."] = "Правила для всього світу, які діють для кожного персонажа в кожній розмові: віч-на-віч, по телефону та в групових чатах. Записуй факти та стиль, наприклад як говорять люди або чого ніхто не знає. Вони ніколи не замінюють власні правила моду.",
    ["For example: Nobody in Night City knows V’s name unless V tells them. Everyone speaks casually."] = "Наприклад: Ніхто в Найт-Сіті не знає імені V, поки V сам його не назве. Усі говорять невимушено.",
    ["Applies to every provider: Local AI, Mistral and Custom in the character prompt, and Convai through its dynamic info."] = "Діє для всіх провайдерів: Local AI, Mistral і Власний у промпті персонажа, а Convai через його динамічну інформацію.",
    ["The world rules are too long. Keep them under {max} characters."] = "Правила світу занадто довгі. Зроби їх коротшими за {max} символів.",
    ["Revert changes"] = "Скасувати зміни",
    ["Clear the world rules?"] = "Очистити правила світу?",
    ["The example lines are too long together. Keep them under {max} characters in all."] = "Приклади реплік разом занадто довгі. Тримай їх у сумі коротшими за {max} символів.",
    ["The speaking style is too long. Keep it under {max} characters."] = "Манера мовлення занадто довга. Тримай її коротшою за {max} символів.",
    ["Things they always know"] = "Що вони завжди знають",
    ["Too many example lines. Keep {max} or fewer."] = "Забагато прикладів реплік. Залиш не більше {max}.",
    ["Too many memories. Keep {max} or fewer."] = "Забагато спогадів. Залиш не більше {max}.",
    ["Too many rules. Keep {max} or fewer."] = "Забагато правил. Залиш не більше {max}.",
    ["Who this character is, what they know and how they look. A long bio makes replies slower, so keep it tight."] = "Хто цей персонаж, що він знає і як виглядає. Довга біографія уповільнює відповіді, тож пиши коротко.",
    ["You have changes that are not saved. Leave without saving?"] = "Є незбережені зміни. Вийти без збереження?",
    ["{count} of {max}"] = "{count} з {max}",
    ["Mature content"] = "Контент для дорослих",
    ["Local AI model"] = "Модель Local AI",
    ["Uncensored model"] = "Модель без цензури",
    ["No model installed"] = "Модель не встановлено",
    ["another model"] = "інша модель",
    ["The Local AI model you chose is missing, does not fit in the free graphics memory or did not start, so {model} was used instead."] = "Вибраної тобою моделі Local AI немає, вона не вміщується у вільну графічну пам’ять або не запустилася, тому натомість використано {model}.",
    ["Local AI switched to {model}: the game is using most of your graphics memory."] = "Local AI перемкнуто на {model}: гра використовує більшу частину відеопам’яті.",
    ["Choose one of the listed Local AI models."] = "Вибери одну з переліку моделей Local AI.",
    ["Characters to invite"] = "Персонажі для запрошення",
    ["Whose memories"] = "Чиї спогади",
    ["Invalid Mature content settings."] = "Недійсні налаштування контенту для дорослих.",
    ["Your message was not sent. Open the text box again and retype it."] = "Твоє повідомлення не надіслано. Відкрий текстове поле знову й введи його ще раз.",
    ["Not usable: {models}. See the Local AI notes, \"Add your own model\"."] = "Недоступні: {models}. Див. нотатки про Local AI, розділ «Додавання власної моделі».",
    ["an embedding model, not a chat model"] = "модель ембедингів, а не чат-модель",
    ["could not be read"] = "не вдалося прочитати",
    ["file not found"] = "файл не знайдено",
    ["not a valid GGUF file"] = "не є дійсним файлом GGUF",
    ["{name} (custom)"] = "{name} (власна)",
    ["{name}: {reason}"] = "{name}: {reason}",
    ["Preparing {name}: waiting for the conversation service to connect…"] = "Підготовка {name}: очікування підключення служби розмов…",
    ["Preparing {name}: waiting for the voice model to load…"] = "Підготовка {name}: очікування завантаження голосової моделі…",
    ["Preparing {name}: waiting for the conversation connection to open…"] = "Підготовка {name}: очікування відкриття з'єднання для розмови…",
    ["Preparing {name}: waiting for the game to place the character…"] = "Підготовка {name}: очікування, поки гра розмістить персонажа…",
    ["Preparing {name}: waiting for the memory service…"] = "Підготовка {name}: очікування служби пам'яті…",
    ["Preparing {count} more companions…"] = "Підготовка інших компаньйонів: {count}…",
    ["The conversation service did not answer. Wait a moment, then invite again."] = "Служба розмов не відповіла. Зачекай мить і запроси знову.",
    ["The voice model did not load. Check the voice in Settings or choose another one, then invite again."] = "Голосову модель не вдалося завантажити. Перевір голос у Налаштуваннях або вибери інший і запроси знову.",
    ["The memory service did not respond. Check your connection, then invite again."] = "Служба пам'яті не відповіла. Перевір з'єднання і запроси знову.",
    ["The conversation connection did not open. Check your connection, then invite again."] = "З'єднання для розмови не відкрилося. Перевір з'єднання і запроси знову.",
    ["Convai sign-in is busy right now. Wait a few minutes, then invite again."] = "Вхід у Convai зараз зайнятий. Зачекай кілька хвилин і запроси знову.",
    ["The Convai daily limit is used up. Choose another provider in Settings, or invite again tomorrow."] = "Денний ліміт Convai вичерпано. Обери іншого провайдера в Налаштуваннях або запроси знову завтра.",
    ["Calls are not available during combat."] = "Дзвінки недоступні під час бою.",
    ["Calls are not available right now."] = "Дзвінки зараз недоступні.",
    ["Holocall ended: combat started."] = "Голодзвінок завершено: почався бій.",
    ["Holocall with {name} ended."] = "Голодзвінок з {name} завершено.",
    ["Live picture unavailable. The call continues with the portrait."] = "Живе зображення недоступне. Дзвінок триває з портретом.",
    ["This contact cannot take a holocall."] = "Цей контакт не може прийняти голодзвінок.",
    ["You are already on a call."] = "Ти вже в розмові.",
    ["A nearby companion makes one short comment as combat starts and another afterward.\n\nTen-minute cooldown after a fight. Conversations and story scenes come first. Loading a save resets the cooldown."] = "Коли починається бій, найближчий компаньйон коротко коментує, а потім ще раз — після нього.\n\nПісля бою — десятихвилинна пауза. Розмови та сюжетні сцени важливіші. Завантаження збереження скидає паузу.",
    ["Ask a companion to drive to your selected map waypoint.\n\nGet into the passenger seat when they are ready."] = "Попроси компаньйона відвезти тебе до обраної на карті позначки.\n\nСідай на пасажирське місце, коли він буде готовий.",
    ["Auto: follows the completed encounter in this save.\n\nCasual: speaks with that familiarity.\n\nOrdinary: keeps her usual manner.\n\nIt does not imply an ongoing relationship."] = "Авто: орієнтується на завершену зустріч у цьому збереженні.\n\nНевимушений: говорить з такою самою невимушеністю.\n\nЗвичайний: зберігає її звичну манеру.\n\nЦе не означає тривалих стосунків.",
    ["Auto: follows the relationship in this save.\n\nRomantic: speaks to V as a partner.\n\nOrdinary: keeps their usual manner.\n\nOnly changes how they talk, never your game choices."] = "Авто: орієнтується на стосунки в цьому збереженні.\n\nРомантичний: звертається до V як до партнера.\n\nЗвичайний: зберігає свою звичну манеру.\n\nЗмінює лише манеру мовлення, але не ігрові вибори.",
    ["Bluetooth audio arrives a little late, so lips and subtitles can run ahead of the voice. This holds them back to match, for every voice.\n\nAuto: 150 ms while Windows plays through Bluetooth, none otherwise. Pick a value if your headset is faster or slower.\n\nThe game’s own dialogue has the same delay and does not correct it."] = "Звук через Bluetooth приходить трохи із запізненням, тож губи й субтитри можуть випереджати голос. Це налаштування притримує їх, щоб узгодити з голосом, для всіх голосів.\n\nАвто: 150 мс, поки Windows відтворює звук через Bluetooth, інакше нічого. Вибери значення, якщо твоя гарнітура швидша чи повільніша.\n\nРепліки самої гри мають таку саму затримку й не виправляються.",
    ["Chat history stays available across game launches.\n\nForgetting a character also clears their saved Chat messages and drafts. Forgetting all memories clears all saved chats."] = "Історія чату зберігається між запусками гри.\n\nЯкщо забути персонажа, також очищаються його збережені повідомлення чату та чернетки. Якщо забути всю пам’ять, очищаються всі збережені чати.",
    ["Companions comment after you finish collecting loot from the world. Storage transfers stay silent.\n\nOrdinary comments are ten minutes apart; newly acquired Legendary gear has its own two-minute cooldown.\n\nPickups made during a fight are folded into one comment at its end."] = "Компаньйони коментують після збирання здобичі у світі. Переміщення в сховищі залишаються без коментарів.\n\nЗвичайні коментарі з’являються раз на десять хвилин; нове легендарне спорядження має власну двохвилинну паузу.\n\nПідбирання під час бою об’єднуються в один коментар наприкінці бою.",
    ["Custom models are ones you added; they join the default choice by size."] = "Власні моделі — це ті, що ти додав; вони беруть участь у типовому виборі за розміром.",
    ["Eyes only: the head stays still and just the eyes move.\n\nSubtle to Strong: the head turns toward you more and more."] = "Лише очі: голова нерухома, рухаються тільки очі.\n\nВід слабкого до сильного: голова дедалі більше повертається до тебе.",
    ["Forget all memories applies to these characters.\n\nBrowsing the catalogue or inviting a companion does not add anyone to this count."] = "«Забути всю пам’ять» стосується цих персонажів.\n\nПерегляд каталогу чи запрошення компаньйона нікого не додає до цього лічильника.",
    ["Gang members, NCPD officers, guards, ripperdocs, shopkeepers, bartenders and passers-by answer as their kind of person.\n\nThey do not know your story and forget you after a save load, except shopkeepers you come back to.\n\nNamed characters are not affected."] = "Члени банд, офіцери NCPD, охоронці, рипердоки, продавці, бармени й перехожі відповідають як представники свого кола.\n\nВони не знають твоєї історії й забувають тебе після завантаження збереження, окрім продавців, до яких ти повертаєшся.\n\nІменованих персонажів це не стосується.",
    ["Talk to story characters"] = "Розмови з персонажами сюжету",
    ["{name} is busy right now."] = "{name} зараз не може говорити.",
    ["{name} is not in your head right now."] = "{name} зараз не у твоїй голові.",
    ["{name} is a story character. Turn on Talk to story characters in Esc > Mods."] = "{name}: персонаж сюжету. Увімкни «Розмови з персонажами сюжету» в Esc > Mods.",
    ["Talk to ordinary NPCs is off. Turn it on in Esc > Mods."] = "Розмови зі звичайними NPC вимкнено. Увімкни їх в Esc > Mods.",
    ["{name} is a child and cannot be talked to."] = "З {name} не можна поговорити: це дитина.",
    ["{name} is not a person and cannot be talked to."] = "З {name} не можна поговорити: це не людина.",
    ["{name} cannot be talked to: the mod cannot tell which voice fits."] = "З {name} не можна поговорити: мод не може визначити, який голос підходить.",
    ["If a character stops answering, voices stop or an error appears: choose Generate report and send the file it names to the developer, with a short note about what you were doing.\n\nThe logs listed below show what went wrong."] = "Якщо персонаж перестає відповідати, голоси зникають або з’являється помилка: вибери «Згенерувати звіт» і надішли розробнику файл, який він назве, з коротким описом того, що ти робив.\n\nЖурнали, перелічені нижче, показують, що пішло не так.",
    ["Invited characters are prepared immediately. Their memories start when you actually talk to them.\n\nOne player identity is shared across all saves and stays the same after forgetting.\n\nCurrent game context describes the world you have loaded."] = "Запрошені персонажі готуються одразу. Їхня пам’ять починається, коли ти справді заговориш із ними.\n\nОдна особистість гравця спільна для всіх збережень і лишається незмінною після забуття.\n\nПоточний контекст гри описує завантажений світ.",
    ["Only Mature models found. Turn on Mature content to use them."] = "Знайдено лише моделі для дорослих. Увімкни Контент для дорослих.",
    ["Something on this PC (a firewall or security software) is blocking the connection to the model server you added."] = "Щось на цьому ПК (брандмауер або програма безпеки) блокує з'єднання з сервером моделі, який ти додав.",
    ["Never allowed: sex with minors or without consent, sex about real people, hate, real-world weapon or drug instructions. A safety check enforces the minors rule."] = "Заборонено: секс з неповнолітніми, без згоди, про реальних людей, ненависть, інструкції зі зброї чи наркотиків. Заборону для неповнолітніх перевіряють.",
    ["Off: replies are text only and no voice is generated.\n\nWith Subtitles off as well, automatic reactions stay silent."] = "Вимкнено: відповіді лише текстові, голос не створюється.\n\nЯкщо вимкнено й субтитри, автоматичні реакції залишаються без звуку.",
    ["See what each character remembers and make one or all of them forget.\n\nMemories are kept across saves."] = "Переглянь, що пам’ятає кожен персонаж, і зітри пам’ять одного або всіх.\n\nСпогади зберігаються між збереженнями.",
    ["Voxtral · not with Mature"] = "Voxtral · не для дорослих",
    ["Voxtral is not used with Mature content."] = "Voxtral не використовується з контентом для дорослих.",
    ["Needs Local AI or Custom."] = "Потрібен Local AI або Власний.",
    ["Mature content is turned off because you chose a model that is not a Mature model."] = "Контент для дорослих вимкнено, бо вибрано модель, яка не для дорослих.",
    ["Strong language, graphic violence, drugs and, between consenting adults, flirting and sex. Adults only (18+). Needs Local AI or Custom."] = "Нецензурна лексика, жорстокість, наркотики та, між дорослими за згодою, фліртування й секс. Лише 18+, потрібен Local AI або Власний.",
    ["From Convai or Mistral, turning it on selects Local AI, or Custom when Local AI is not installed. With Local AI it also selects the largest uncensored model that fits. Turning it off restores your choices."] = "Якщо увімкнути з Convai або Mistral, вибирається Local AI, а коли Local AI не встановлено, — Власний. З Local AI також вибирається найбільша підхожа модель без цензури. Вимкнення повертає твій вибір.",
    ["Choosing Convai or Mistral turns it off. Voxtral is not used with it: a voice on Voxtral moves to Pocket and comes back when it is turned off."] = "Вибір Convai або Mistral вимикає це. Voxtral з цим не використовується: голос на Voxtral переходить на Pocket і повертається після вимкнення.",
    ["Use it if companions seem to look above or below your eyes."] = "Вмикай, якщо компаньйони ніби дивляться вище або нижче твоїх очей.",
    ["Voxtral · Mistral cloud"] = "Voxtral · Хмара Mistral",
    ["Voxtral · needs Mistral key"] = "Voxtral · треба ключ Mistral",
    ["{name} (custom · too large)"] = "{name} (власна · завелика)",
    ["{name} (custom, {size} GB, needs {need} GB)"] = "{name} (власна, {size} ГБ, потрібно {need} ГБ)",
    ["{name} (custom, {size} GB, too large for this card)"] = "{name} (власна, {size} ГБ, завелика для цієї відеокарти)",
    ["Clear memories about you for every character you have talked to.\n\nYour player identity stays. A confirmation comes first."] = "Очисти пам’ять про тебе у всіх персонажів, з якими відбувалися розмови.\n\nІдентичність гравця зберігається. Спершу потрібне підтвердження.",
    ["Saves a report file you can send to the developer.\n\nAPI keys, tokens, IDs, microphone audio and conversation text are left out. Without the conversation service, a shorter report is made from the files the game can read."] = "Збережи файл звіту, який можна надіслати розробнику.\n\nAPI-ключі, токени, ідентифікатори, звук мікрофона й текст розмов не включаються. Без служби розмов створюється коротший звіт із файлів, які може прочитати гра.",
    ["The Mature pack’s uncensored models (for Local AI) give the full effect; standard models mostly refuse sex. Pack: installed."] = "Моделі без цензури з Mature pack (для Local AI) дають повний ефект; звичайні часто відмовляють у сексі. Пакет: встановлено.",
    ["The Mature pack’s uncensored models (for Local AI) give the full effect; standard models mostly refuse sex. Pack: not installed (optional, on this mod’s Hugging Face page)."] = "Моделі без цензури з Mature pack (для Local AI) дають повний ефект; звичайні часто відмовляють у сексі. Пакет: не встановлено (необов’язково, сторінка моду на Hugging Face).",
    ["Until you choose one, Local AI loads the largest model that fits your free graphics memory.\n\nOne model at a time; a change applies when it next loads. A model that is missing, too large or failing is replaced by the largest that fits, with one notice."] = "Без вибору Local AI завантажує найбільшу модель, що вміститься у вільну відеопам’ять.\n\nОдна модель за раз; зміна діє при наступному завантаженні. Відсутню, завелику або збійну модель замінює найбільша підхожа, з одним сповіщенням.",
    ["Convai did not accept your API key. Check it in Settings > Conversation provider."] = "Convai не прийняв твій API-ключ. Перевір його в меню Налаштування > Постачальник розмов.",
    ["Local AI could not start. Check Local AI in Settings > Conversation provider."] = "Local AI не вдалося запустити. Перевір Local AI в Налаштуваннях > Постачальник розмов.",
    ["Mistral did not accept your key. Check it in Settings > Conversation provider."] = "Mistral не прийняв твій ключ. Перевір його в меню Налаштування > Постачальник розмов.",
    ["Mistral has no key yet, so Convai is used. Add your key in Settings > Conversation provider."] = "Для Mistral ще немає ключа, тож використовується Convai. Додай свій ключ у меню Налаштування > Постачальник розмов.",
    ["Requires a Mistral key (add it in Settings > Conversation provider)"] = "Потрібен ключ Mistral (додай його в Налаштування > Постачальник розмов)",
    ["Speaking to companions needs Convai for now. Set Conversation provider to Convai free tier in Settings > Conversation provider, or type your message."] = "Розмова з компаньйонами поки що потребує Convai. Встанови для параметра Постачальник розмов значення Convai (безкоштовний тариф) в меню Налаштування > Постачальник розмов або напиши повідомлення.",
    ["The conversation limit has been reached. Try again later, or add a free Mistral key and set Conversation provider to Mistral in Settings > Conversation provider."] = "Досягнуто ліміт розмов. Спробуй пізніше або додай безкоштовний ключ Mistral і в меню Налаштування > Постачальник розмов встанови Постачальника розмов: Mistral.",
    ["Convai could not sign in. Try again in a moment, or choose Mistral or Local AI in Settings > Conversation provider."] = "Не вдалося увійти в Convai. Спробуй за мить або обери Mistral чи Local AI в меню Налаштування > Постачальник розмов.",
    ["Your Convai API key has reached its plan limit. Try again later or add a different key in Settings > Conversation provider."] = "Твій API-ключ Convai досяг ліміту тарифу. Спробуй пізніше або додай інший ключ у меню Налаштування > Постачальник розмов.",
    ["You’ve reached today’s Convai free tier limit. It resets tomorrow. To keep talking now, choose another provider in Settings > Conversation provider. Mistral (free, with your own free key) allows about 5,000 turns a day. Local AI is unlimited and runs on your PC."] = "Ти вичерпав сьогоднішній ліміт безкоштовного тарифу Convai. Він оновиться завтра. Щоб продовжити розмову зараз, обери іншого постачальника в меню Налаштування > Постачальник розмов. Mistral (безкоштовно, з твоїм власним безкоштовним ключем) дозволяє приблизно 5 000 повідомлень на день. Local AI без ліміту і працює на твоєму комп’ютері.",
    ["Today’s {limit} Convai turns are used.\nTry Mistral (free key, ~5,000 a day) or Local AI (unlimited)."] = "Convai: вичерпано {limit}.\nMistral (безкоштовно, ~5 000/день) чи Local AI (безліміт).",
    ["Today’s Convai turns are used.\nTry Mistral (free key, ~5,000 a day) or Local AI (unlimited)."] = "Ліміт Convai вичерпано.\nMistral (безкоштовно, ~5 000/день) чи Local AI (безліміт).",
    ["Convai is answering right now, so these changes have no effect yet. Choose Mistral, Local AI or Custom as the conversation provider in the settings."] = "Convai зараз відповідає, тому ці зміни поки не діють. Вибери в налаштуваннях Mistral, Local AI або Власний як постачальника розмов.",
    ["Your changes work with Mistral, Local AI and Custom. They do not apply to Convai."] = "Твої зміни працюють із Mistral, Local AI і Власним. На Convai вони не діють.",
    ["Paste"] = "Вставити",
    ["no Omni pack"] = "без пакета Omni",
    ["Add your Convai API key below to see and buy a plan."] = "Щоб побачити плани й купити один із них, додай свій API-ключ Convai внизу.",
    ["Add your Convai API key first."] = "Спершу додай API-ключ Convai.",
    ["Add your Convai API key first: copy it, then choose Paste on the Convai API key row."] = "Спершу додай API-ключ Convai: скопіюй його, а потім вибери «Вставити» в рядку «API-ключ Convai».",
    ["Asking Convai for the payment page…"] = "Запит сторінки оплати в Convai…",
    ["Asks Convai which plan your key has now. After paying, it can take about 15 seconds."] = "Convai перевіряє, який план зараз має твій ключ. Після оплати це може тривати близько 15 секунд.",
    ["Billed every month."] = "Списується щомісяця.",
    ["Billed once a year."] = "Списується раз на рік.",
    ["Buy"] = "Купити",
    ["Check"] = "Перевірити",
    ["Check my plan"] = "Перевірити мій план",
    ["Checking your plan…"] = "Перевірка плану…",
    ["Choose Check my plan to ask Convai."] = "Вибери «Перевірити мій план», щоб запитати в Convai.",
    ["Contacting Convai…"] = "Зв’язок із Convai…",
    ["Convai could not start the payment. Try again later."] = "Convai не змогло розпочати оплату. Спробуй пізніше.",
    ["Convai did not accept your API key."] = "Convai не прийняло твій API-ключ.",
    ["Convai does not show a paid plan for your key yet."] = "Convai поки що не показує платного плану для твого ключа.",
    ["Convai has not confirmed your plan yet. Check it in Settings > Convai paid tier."] = "Convai ще не підтвердило твій план. Перевір це в розділі «Налаштування > Платний рівень Convai».",
    ["Convai paid tier"] = "Платний рівень Convai",
    ["Convai’s payment page is open in your browser. Your plan is active about 15 seconds after you pay."] = "Сторінка оплати Convai відкрита у твоєму браузері. Твій план активується приблизно через 15 секунд після оплати.",
    ["Convai’s payment service did not answer. Try again in a moment."] = "Служба оплати Convai не відповіла. Спробуй ще раз за мить.",
    ["Convai’s plans for this mod: more Convai conversations on your own Convai API key. Opens a page with the plans and their prices."] = "Плани Convai для цього моду: більше розмов Convai з твоїм власним API-ключем Convai. Відкриває сторінку з планами та їх цінами.",
    ["Conversations with Convai API key chosen as the provider use this plan."] = "Розмови, коли постачальником вибрано API-ключ Convai, використовують цей план.",
    ["Get your Convai API key"] = "Отримай свій API-ключ Convai",
    ["Manage or cancel plan"] = "Керувати планом або скасувати",
    ["Free"] = "Безкоштовно",
    ["Gamer, monthly"] = "Gamer, щомісяця",
    ["Gamer, yearly"] = "Gamer, щороку",
    ["Gamer Pro, monthly"] = "Gamer Pro, щомісяця",
    ["Gamer Pro, yearly"] = "Gamer Pro, щороку",
    ["Current plan"] = "Поточний план",
    ["This is your current plan. To change or cancel it, choose Manage or cancel plan below."] = "Це твій поточний план. Щоб змінити або скасувати його, обери нижче «Керувати планом або скасувати».",
    ["No key added"] = "Ключ не додано",
    ["Not checked yet"] = "Ще не перевірено",
    ["Opened in your browser."] = "Відкрито у твоєму браузері.",
    ["Opening the page in your browser…"] = "Відкриття сторінки у твоєму браузері…",
    ["Opens Convai’s payment page (Stripe) in your browser. You pay Convai directly; the mod never sees your card. Your plan is active about 15 seconds after you pay, and conversations then use your Convai API key."] = "Відкриває сторінку оплати Convai (Stripe) у браузері. Ти платиш Convai напряму; мод ніколи не бачить твою картку. Твій план активується приблизно через 15 секунд після оплати, а розмови далі використовують твій API-ключ Convai.",
    ["Opens convai.com in your browser. Sign in or make a free account, copy your API key, then come back and choose Paste below."] = "Відкриває convai.com у браузері. Увійди або створи безкоштовний обліковий запис, скопіюй свій API-ключ, потім повернись і вибери «Вставити» нижче.",
    ["Opens your Convai billing page in your browser. Sign in with the same Convai account to change or cancel your plan."] = "Відкриває твою сторінку рахунків Convai у браузері. Увійди в той самий обліковий запис Convai, щоб змінити або скасувати план.",
    ["Plans"] = "Плани",
    ["Plans Convai made for this mod. They give your own Convai API key more conversations; the free tier stays as it is."] = "Плани, які Convai створило для цього моду. Вони дають твоєму власному API-ключу Convai більше розмов; безкоштовний рівень лишається без змін.",
    ["Prices in US dollars. You can cancel at any time on Convai’s billing page."] = "Ціни в доларах США. Скасувати можна будь-коли на сторінці рахунків Convai.",
    ["The conversation service is not running, so plans cannot be shown. Restart the game."] = "Служба розмов не працює, тому плани показати не можна. Перезапусти гру.",
    ["This key has no paid plan. Choose a plan below."] = "Для цього ключа немає платного плану. Вибери план нижче.",
    ["Your Convai plan"] = "Твій план Convai",
    ["Your Convai plan is active."] = "Твій план Convai активний.",
    ["Your Convai plan is active. Choose Convai API key in Settings > Conversation provider."] = "Твій план Convai активний. Вибери «API-ключ Convai» у розділі «Налаштування > Постачальник розмов».",
    ["Your Convai plan is active. Conversations now use your Convai API key."] = "Твій план Convai активний. Розмови тепер використовують твій API-ключ Convai.",
    ["Your browser could not be opened."] = "Не вдалося відкрити браузер.",
    ["Your plan could not be read right now. Try again in a moment."] = "Зараз не вдалося прочитати план. Спробуй ще раз за мить.",
    ["{count} Convai interactions a month."] = "{count} взаємодій Convai на місяць.",
    ["{plan}, {price} a month"] = "{plan}, {price} на місяць",
    ["{plan}, {price} a year"] = "{plan}, {price} на рік",
    ["Sign in with Convai"] = "Увійти через Convai",
    ["Sign in"] = "Увійти",
    ["Opens Convai’s sign-in page in your browser.\n\nSign in or make a free account, and your Convai API key is saved on this computer, the same as Paste. You have five minutes."] = "Відкриває сторінку входу Convai у браузері.\n\nУвійди або створи безкоштовний обліковий запис, і твій API-ключ Convai збережеться на цьому комп’ютері, так само як при «Вставити». У тебе є п’ять хвилин.",
    ["Opening Convai’s sign-in page in your browser…"] = "Відкриваємо сторінку входу Convai у браузері…",
    ["Sign in on the Convai page in your browser. Your key is saved here when you finish."] = "Увійди на сторінці Convai у браузері. Коли завершиш, ключ збережеться тут.",
    ["Signed in. Your Convai API key is saved."] = "Вхід виконано. Твій API-ключ Convai збережено.",
    ["The sign-in took too long. Choose Sign in with Convai to try again."] = "Вхід тривав занадто довго. Вибери «Увійти через Convai», щоб спробувати знову.",
    ["The sign-in did not finish. Try again, or copy your key from convai.com and choose Paste."] = "Вхід не завершено. Спробуй ще раз або скопіюй ключ з convai.com і вибери «Вставити».",
    ["Choose one of the listed voices for V."] = "Вибери один із перелічених голосів для V.",
    ["Pocket · On your PC"] = "Pocket · На твоєму ПК",
    ["Johnny in your head"] = "Johnny у твоїй голові",
    ["Johnny in your head is off. Turn it on in Settings > Conversations."] = "Johnny у твоїй голові вимкнено. Увімкни його в Налаштуваннях > Розмови.",
    ["Choose how often Johnny speaks up."] = "Обери, як часто Johnny озивається.",
    ["A clip you add replaces the shipped voice of this character for Pocket, OmniVoice and the Voxtral cloud voice."] = "Кліп, який ти додаси, замінює вихідний голос цього персонажа для Pocket, OmniVoice і хмарного голосу Voxtral.",
    ["A display name is too long. Keep each one under {max} characters."] = "Відображуване ім’я занадто довге. Кожне має бути коротшим за {max} символів.",
    ["A new or removed clip counts from the next line this character speaks, once the current reply is over. Nothing needs restarting."] = "Новий або видалений кліп діє з наступної репліки цього персонажа, коли закінчиться поточна відповідь. Нічого перезапускати не потрібно.",
    ["A record name can only use letters, digits, dots, dashes and underscores, for example Character.Rebecca."] = "Ім’я запису може містити лише літери, цифри, крапки, дефіси та підкреслення, наприклад Character.Rebecca.",
    ["Add a display name"] = "Додати відображуване ім’я",
    ["Add a record name"] = "Додати ім’я запису",
    ["Add a record name or a display name, so the game can find this character."] = "Додай ім’я запису або відображуване ім’я, щоб гра могла знайти цього персонажа.",
    ["Add voice clip"] = "Додати голосовий кліп",
    ["Another character of yours, {other}, already answers to this record or name."] = "Інший твій персонаж, {other}, уже відгукується на цей запис або ім’я.",
    ["Choose a gender"] = "Вибери стать",
    ["Choose a gender."] = "Вибери стать.",
    ["Chosen file: {name} ({size}). It is checked when you save it."] = "Вибраний файл: {name} ({size}). Його буде перевірено, коли ти його збережеш.",
    ["Chosen file: {name}, {seconds} seconds."] = "Вибраний файл: {name}, {seconds} с.",
    ["Clip removed."] = "Кліп видалено.",
    ["Delete character"] = "Видалити персонажа",
    ["Delete {name}? The character, its voice clip and what it remembers of you are removed."] = "Видалити {name}? Персонаж, його голосовий кліп і все, що він пам’ятає про тебе, буде видалено.",
    ["Display names"] = "Відображувані імена",
    ["Female"] = "Жіноча",
    ["Filled in from the character you were facing: {name}."] = "Заповнено за персонажем, якого ти бачив перед собою: {name}.",
    ["For example: Character.Rebecca"] = "Наприклад: Character.Rebecca",
    ["For example: Rebecca"] = "Наприклад: Rebecca",
    ["Gender"] = "Стать",
    ["Give the character a name."] = "Дай персонажу ім’я.",
    ["How the game finds this character"] = "Як гра знаходить цього персонажа",
    ["It picks the voice when the character has no clip."] = "Якщо в персонажа немає кліпу, голос обирає стать.",
    ["Male"] = "Чоловіча",
    ["Memories"] = "Спогади",
    ["Name"] = "Ім’я",
    ["New character"] = "Новий персонаж",
    ["No clip yet."] = "Кліпу поки немає.",
    ["Optional. Pocket, OmniVoice and the Voxtral cloud voice copy a clip you add. Without one the character speaks with a generic voice that fits the gender."] = "Необов’язково. Pocket, OmniVoice і хмарний голос Voxtral копіюють кліп, який ти додаси. Без нього персонаж говорить звичайним голосом, що відповідає статі.",
    ["Play saved clip"] = "Відтворити збережений кліп",
    ["Record names"] = "Імена записів",
    ["Remove clip"] = "Видалити кліп",
    ["Remove the voice clip? The character goes back to a generic voice."] = "Видалити голосовий кліп? Персонаж повернеться до звичайного голосу.",
    ["Remove the voice clip? {name} goes back to the shipped voice."] = "Видалити голосовий кліп? {name} повернеться до вихідного голосу.",
    ["Save clip"] = "Зберегти кліп",
    ["Save the character first. Then it can have a voice clip, and it starts to remember your talks."] = "Спершу збережи персонажа. Після цього в нього може з’явитися голосовий кліп, і він почне запам’ятовувати твої розмови.",
    ["Saved clip: {seconds} seconds."] = "Збережений кліп: {seconds} с.",
    ["Saved. The clip is a little long: 10 to 18 seconds copies best."] = "Збережено. Кліп трохи довгий: найкраще копіюються кліпи від 10 до 18 секунд.",
    ["Saved. The clip is a little short: 10 to 18 seconds copies best."] = "Збережено. Кліп трохи короткий: найкраще копіюються кліпи від 10 до 18 секунд.",
    ["That file is not a recording the voices can read. Use a WAV, MP3, OGG or FLAC file."] = "Це не запис, який голоси можуть прочитати. Використай файл WAV, MP3, OGG або FLAC.",
    ["That file is too big for a voice clip."] = "Цей файл занадто великий для голосового кліпу.",
    ["The clip is mostly silence. Use a clip where somebody is talking most of the time."] = "Кліп майже весь складається з тиші. Використай кліп, у якому хтось говорить більшу частину часу.",
    ["The clip is too long. Use at most {max} seconds."] = "Кліп занадто довгий. Використай не більше {max} секунд.",
    ["The clip is too short. Use at least {min} seconds."] = "Кліп занадто короткий. Використай щонайменше {min} секунд.",
    ["The game did not name anyone. Face the character, then choose Settings > Edit characters > Open in the game again."] = "Гра нікого не назвала. Повернися до персонажа, а потім у грі знову вибери Налаштування > Редагувати персонажів > Відкрити.",
    ["The game recognises the person you talk to by a record name, a display name, or both. A record name looks like Character.Rebecca or NCA.Rebecca. Add at least one."] = "Гра розпізнає співрозмовника за іменем запису, відображуваним іменем або обома. Ім’я запису виглядає так: Character.Rebecca або NCA.Rebecca. Додай принаймні одне.",
    ["The name is too long. Keep it under {max} characters."] = "Ім’я занадто довге. Тримай його коротшим за {max} символів.",
    ["The name of the character’s record in the game files."] = "Ім’я запису персонажа у файлах гри.",
    ["The name the character goes by. They give it when somebody asks who they are."] = "Ім’я, яким користується персонаж. Він його називає, коли хтось питає, хто він.",
    ["The name the game shows for the character."] = "Ім’я, яке гра показує для персонажа.",
    ["The recording is distorted. Record it again, a little quieter."] = "Запис спотворений. Запиши його знову, трохи тихіше.",
    ["The recording is too low in quality. Use at least {min} Hz."] = "Якість запису занадто низька. Використай щонайменше {min} Hz.",
    ["The recording is too quiet to copy. Record it louder, or closer to the microphone."] = "Запис занадто тихий, щоб його скопіювати. Запиши гучніше або ближче до мікрофона.",
    ["The saved clip could not be loaded."] = "Не вдалося завантажити збережений кліп.",
    ["The words said in the clip are too long. Keep them under {max} characters."] = "Слова в кліпі занадто довгі. Тримай їх коротшими за {max} символів.",
    ["This character speaks with a generic voice that fits the gender."] = "Цей персонаж говорить звичайним голосом, що відповідає статі.",
    ["This character speaks with the shipped voice."] = "Цей персонаж говорить вихідним голосом.",
    ["This computer cannot convert that file. Save it as a WAV and try again."] = "Цей комп’ютер не може перетворити цей файл. Збережи його як WAV і спробуй ще раз.",
    ["Too many display names. Keep {max} or fewer."] = "Забагато відображуваних імен. Залиш не більше {max}.",
    ["Too many record names. Keep {max} or fewer."] = "Забагато імен записів. Залиш не більше {max}.",
    ["Type the words said in the clip, at least {min} characters."] = "Введи слова, сказані в кліпі, щонайменше {min} символів.",
    ["Type what the clip says, as spoken. OmniVoice needs it to copy the voice."] = "Введи, що каже кліп, так, як це вимовляється. OmniVoice потрібно це, щоб скопіювати голос.",
    ["Use the character I’m facing"] = "Використати персонажа, на якого я дивлюсь",
    ["Use {min} to {max} seconds of one person speaking clearly, with no music or other voices. {goodMin} to {goodMax} seconds copies best. WAV, MP3, OGG or FLAC."] = "Використай від {min} до {max} секунд чіткої мови однієї людини, без музики й інших голосів. Найкраще копіюється кліп тривалістю від {goodMin} до {goodMax} секунд. WAV, MP3, OGG або FLAC.",
    ["Voice"] = "Голос",
    ["Who this character is, what they know and how they look. Writing it as “I am …” works best. A long bio makes replies slower, so keep it tight."] = "Хто цей персонаж, що він знає і як виглядає. Найкраще писати у формі «Я …». Довга біографія сповільнює відповіді, тому тримай її стислою.",
    ["Words said in the clip"] = "Слова, сказані в кліпі",
    ["You have as many voice clips as the editor keeps ({max}). Remove one first."] = "Ти вже маєш стільки голосових кліпів, скільки може зберегти редактор ({max}). Спершу видали один.",
    ["You have made as many characters as the editor keeps ({max}). Delete one first."] = "Ти вже створив стільки персонажів, скільки може зберегти редактор ({max}). Спершу видали один.",
    ["Your character"] = "Твій персонаж",
    ["Your characters"] = "Твої персонажі",
    ["Your own characters talk only with Mistral, Local AI or Custom. With Convai they speak as an ordinary person."] = "Твої власні персонажі розмовляють лише з Mistral, Local AI або Власним. З Convai вони говорять як звичайні люди.",
    ["{name} is one of your own characters. They need Mistral, Local AI or Custom, so with Convai they talk as an ordinary person."] = "{name} — один із твоїх власних персонажів. Йому потрібен Mistral, Local AI або Власний, тому з Convai він говорить як звичайна людина.",
    ["{other} already has a profile in the mod, and that profile always wins. Use another record or name."] = "{other} уже має профіль у моді, і цей профіль завжди має перевагу. Використай інший запис або ім’я.",
    ["A pack is one folder too deep. See Help in Settings."] = "Пакет на одну папку глибше. Див. Довідку в Налаштуваннях.",
    ["All files found."] = "Усі файли знайдено.",
    ["Browser"] = "Браузер",
    ["Found."] = "Знайдено.",
    ["Found: {list}."] = "Знайдено: {list}.",
    ["Game version"] = "Версія гри",
    ["Graphics card"] = "Відеокарта",
    ["Internet"] = "Інтернет",
    ["Loaded."] = "Завантажено.",
    ["Local AI could not start. Generate a report below and send it, or choose another conversation provider."] = "Local AI не вдалося запустити. Згенеруй звіт нижче й надішли його або обери іншого постачальника розмов.",
    ["Local AI found no graphics card it can use. It needs an NVIDIA or AMD card with a current driver. Update the driver, or choose another conversation provider."] = "Local AI не знайшов придатної відеокарти. Потрібна карта NVIDIA або AMD з актуальним драйвером. Онови драйвер або обери іншого постачальника розмов.",
    ["Missing: {files}. Extract the Scripts zip into the Cyberpunk 2077 folder again and let it replace the files."] = "Відсутні: {files}. Розпакуй архів Scripts у папку Cyberpunk 2077 ще раз і дозволь замінити файли.",
    ["Mod files"] = "Файли моду",
    ["Mod manager"] = "Менеджер модів",
    ["Moved into place from {folder}: {packs}."] = "Переміщено з {folder}: {packs}.",
    ["No Local AI pack found. Download one from the mod’s Hugging Face page and extract it into the Cyberpunk 2077 folder, or choose another conversation provider."] = "Пакет Local AI не знайдено. Завантаж його зі сторінки моду на Hugging Face і розпакуй у папку Cyberpunk 2077 або обери іншого постачальника розмов.",
    ["No problem found. Select a line to see what was checked."] = "Проблем не знайдено. Вибери рядок, щоб побачити, що перевірено.",
    ["No sign of the conversation service in this session: the Runtime is missing or did not load. Extract the full install zip (AI-NPC-LLM-Companions) straight into the Cyberpunk 2077 folder (not into a new folder), check that red4ext/plugins/AiNpcCyberpunkMod is there, then restart the game. The full install is on the mod’s Nexus Mods page."] = "У цій сесії немає ознак служби розмов: Runtime відсутній або не завантажився. Розпакуй повний установочний zip (AI-NPC-LLM-Companions) просто в папку Cyberpunk 2077 (не в нову папку), перевір, що там є red4ext/plugins/AiNpcCyberpunkMod, і перезапусти гру. Повний установочний zip є на сторінці моду на Nexus Mods.",
    ["None found: installed by hand."] = "Не знайдено: встановлено вручну.",
    ["None installed. They are optional."] = "Нічого не встановлено. Вони необов’язкові.",
    ["Not needed: Local AI and the voice run on this PC."] = "Не потрібно: Local AI та голос працюють на цьому ПК.",
    ["Not used"] = "Не використовується",
    ["Not your conversation provider. Choose it in Settings > Conversation provider."] = "Це не твій постачальник розмов. Обери його в меню Налаштування > Постачальник розмов.",
    ["Note"] = "Примітка",
    ["OK"] = "OK",
    ["Optional packs"] = "Додаткові пакети",
    ["Problem"] = "Проблема",
    ["Problems found: {count}. Select a line marked Problem to read what to do."] = "Знайдено проблем: {count}. Вибери рядок із позначкою «Проблема», щоб прочитати, що робити.",
    ["RED4ext is not loaded. Install it from Nexus Mods, then restart the game. It also starts the conversation service."] = "RED4ext не завантажено. Встанови його з Nexus Mods і перезапусти гру. Він також запускає службу розмов.",
    ["Reached {host}."] = "Підключено до {host}.",
    ["Scripts and Runtime"] = "Scripts і Runtime",
    ["Scripts {scripts} and Runtime {runtime}."] = "Scripts {scripts} і Runtime {runtime}.",
    ["Scripts {scripts} on Runtime base {runtime}."] = "Scripts {scripts} на базі Runtime {runtime}.",
    ["These Scripts {scripts} need the Runtime base {required} or newer, and your Runtime is {runtime}. Extract the full install zip (AI-NPC-LLM-Companions, on Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Цим Scripts {scripts} потрібна база Runtime {required} або новіша, а твій Runtime — {runtime}. Розпакуй повний установочний zip (AI-NPC-LLM-Companions, на Nexus Mods) у папку Cyberpunk 2077, потім перезапусти гру.",
    ["The Runtime is older than {required}. Get the full install zip."] = "Runtime старіший за {required}. Візьми повний ZIP.",
    ["Setup check"] = "Перевірка встановлення",
    ["Some mod files are missing. Extract the update zip again. See Help in Settings."] = "Не вистачає файлів моду. Розпакуй Update-ZIP ще раз. Див. Довідку в Налаштуваннях.",
    ["Some pack files could not be moved into place because different files are already there. Extract the pack into the Cyberpunk 2077 folder again and let it replace the files."] = "Деякі файли пакета не вдалося перемістити, бо на їх місці вже є інші файли. Розпакуй пакет у папку Cyberpunk 2077 ще раз і дозволь замінити файли.",
    ["The Runtime is incomplete ({code}). Extract the full install zip (AI-NPC-LLM-Companions) into the Cyberpunk 2077 folder again and let it replace the files, then restart the game."] = "Runtime неповний ({code}). Розпакуй повний установочний zip (AI-NPC-LLM-Companions) заново в папку Cyberpunk 2077, замінивши файли, і перезапусти гру.",
    ["The settings file of the launcher, launcher.ini, is missing from red4ext/plugins/AiNpcCyberpunkMod, so the game cannot start the conversation service. Extract the full install zip (AI-NPC-LLM-Companions) straight into the Cyberpunk 2077 folder again (by hand, also with Vortex) and let it replace the files, then restart the game."] = "Файл налаштувань запуску launcher.ini відсутній у red4ext/plugins/AiNpcCyberpunkMod, тому гра не може запустити службу розмов. Розпакуй повний установочний zip (AI-NPC-LLM-Companions) заново просто в папку Cyberpunk 2077 (вручну, навіть якщо користуєшся Vortex), замінивши файли, і перезапусти гру.",
    ["The conversation service cannot reach the internet. See Help in Settings."] = "Служба розмов не має доступу до інтернету. Див. Довідку в Налаштуваннях.",
    ["The conversation service cannot reach {host}. Allow Node.js through your firewall or antivirus (Windows asks once; choose Allow), check your internet, then restart the game."] = "Служба розмов не може звернутися до {host}. Дозволь Node.js у брандмауері або антивірусі (Windows запитає один раз; обери «Дозволити доступ»), перевір інтернет і перезапусти гру.",
    ["The conversation service could not start ({code}). Restart the game. If it happens again, generate a report below and send it."] = "Службу розмов не вдалося запустити ({code}). Перезапусти гру. Якщо це повториться, згенеруй звіт нижче й надішли його.",
    ["The conversation service did not start. Is the Runtime installed? See Help in Settings."] = "Служба розмов не запустилася. Runtime встановлено? Див. Довідку в Налаштуваннях.",
    ["The game version could not be read."] = "Не вдалося визначити версію гри.",
    ["This PC cannot look up {host}. Check your internet connection, then restart the game."] = "Цей ПК не може знайти {host}. Перевір підключення до інтернету й перезапусти гру.",
    ["Open r6/logs/redscript_rCURRENT.log. A mod it names is why the scripts did not load."] = "Відкрий r6/logs/redscript_rCURRENT.log. Названий там мод блокує скрипти.",
    ["This mod’s scripts did not load. Open r6/logs/redscript_rCURRENT.log. If the error names another mod, that mod is the problem. Missing or old Codeware or redscript, or a game version other than {game}, can also cause it."] = "Скрипти цього моду не завантажилися. Відкрий r6/logs/redscript_rCURRENT.log. Якщо в помилці названо інший мод, проблема в ньому. Причиною також можуть бути відсутній або застарілий Codeware чи redscript, або версія гри, відмінна від {game}.",
    ["Missing: {names}. Install them and restart the game."] = "Відсутні: {names}. Встанови їх і перезапусти гру.",
    ["Install or update: {names}. Then restart the game."] = "Встанови або онови: {names}. Потім перезапусти гру.",
    ["Codeware is too old. Update it from Nexus Mods, then restart the game."] = "Codeware занадто старий. Онови його з Nexus Mods і перезапусти гру.",
    ["Version {version}."] = "Версія {version}.",
    ["Version {version}. The mod is tested on {game} only, so some things may not work."] = "Версія {version}. Мод перевірено лише на {game}, тож деякі речі можуть не працювати.",
    ["Version {version}. These files are the mod build for game {build}. Extract the full install zip made for game {game}, from the mod’s Nexus Mods page, into the Cyberpunk 2077 folder, then restart the game."] = "Версія {version}. Ці файли — збірка мода для гри {build}. Розпакуй повний установочний zip для гри {game} зі сторінки мода на Nexus Mods у папку Cyberpunk 2077, потім перезапусти гру.",
    ["Vortex. Install the optional packs by hand into the Cyberpunk 2077 folder, as the install steps say. Install the full install zip as one mod and update that mod with each new full install zip."] = "Vortex. Встанови необов’язкові пакети вручну в папку Cyberpunk 2077, як сказано в кроках встановлення. Повний установочний zip встанови одним модом і оновлюй цей мод кожним новим повним установочним zip.",
    ["{name} is missing. Install it from Nexus Mods, then restart the game."] = "Немає {name}. Встанови його з Nexus Mods і перезапусти гру.",
    ["{name}, {memory} GB of video memory."] = "{name}, {memory} ГБ відеопам’яті.",
    ["{packs} is one folder too deep, in {folder}. Restart the game and the mod moves it into place. If it is still there afterwards, move the red4ext folder inside it into the Cyberpunk 2077 folder."] = "{packs} лежить на одну папку глибше, ніж треба, у {folder}. Перезапусти гру, і мод сам перемістить файли на місце. Якщо вони залишаться там, перемісти папку red4ext, що всередині, у папку Cyberpunk 2077.",
    ["Add an endpoint URL and a model ID first."] = "Спершу додай URL ендпоінта та ID моделі.",
    ["Convai: the custom provider is not set up yet"] = "Convai: власний постачальник ще не налаштовано",
    ["Copy the base URL from your provider, for example https://openrouter.ai/api/v1, https://nano-gpt.com/api/v1 or http://localhost:11434/v1 (Ollama). It is read from the clipboard once and saved on this computer.\n\nOnly this computer and your home network may use http://. You can also fill in endpoint=, model= and api-key= in player-custom-endpoint.txt in the conversation service folder.\n\nNothing is sent until you choose this provider or press Test connection."] = "Скопіюй базовий URL у свого постачальника, наприклад https://openrouter.ai/api/v1, https://nano-gpt.com/api/v1 або http://localhost:11434/v1 (Ollama). Його один раз зчитують із буфера обміну й зберігають на цьому комп’ютері.\n\nhttp:// можна використовувати лише на цьому комп’ютері та в домашній мережі. Також можна вказати endpoint=, model= та api-key= у файлі player-custom-endpoint.txt у папці служби розмов.\n\nНічого не надсилається, доки ти не обереш цього постачальника або не натиснеш «Перевірити зв’язок».",
    ["Copy the model ID from your provider first, for example meta-llama/llama-3.1-8b-instruct on OpenRouter or llama3.2 on Ollama. It is read from the clipboard once and saved on this computer."] = "Спершу скопіюй ID моделі у свого постачальника, наприклад meta-llama/llama-3.1-8b-instruct (OpenRouter) або llama3.2 (Ollama). Його один раз зчитують із буфера обміну й зберігають на цьому комп’ютері.",
    ["Copy your API key from your provider first. It is read from the clipboard once and saved on this computer only. A server on your own computer, such as Ollama or LM Studio, usually needs no key."] = "Спершу скопіюй API-ключ у свого постачальника. Його один раз зчитують із буфера обміну й зберігають лише на цьому комп’ютері. Локальному серверу, як-от Ollama чи LM Studio, ключ зазвичай не потрібен.",
    ["Custom (OpenAI-compatible)"] = "Власний (OpenAI-compatible)",
    ["Custom API key"] = "Власний API-ключ",
    ["Custom endpoint URL"] = "Власний URL ендпоінта",
    ["Custom model ID"] = "Власний ID моделі",
    ["Custom provider replies are spoken by a local voice instead of the Convai cloud voice."] = "Відповіді власного постачальника читає місцевий голос, а не хмарний голос Convai.",
    ["Custom: key not accepted"] = "Власний: ключ не прийнято",
    ["Custom: model unavailable"] = "Власний: модель недоступна",
    ["Custom: out of credits"] = "Власний: закінчилися кредити",
    ["Custom: rate limited for now"] = "Власний: тимчасово обмежено",
    ["Deletes the saved endpoint URL. The custom provider needs one to answer."] = "Видаляє збережений URL ендпоінта. Власному постачальнику він потрібен для відповідей.",
    ["Deletes the saved key. Replies from the custom provider are then asked for without a key."] = "Видаляє збережений ключ. Далі відповіді власного постачальника запитуються без ключа.",
    ["Deletes the saved model ID. The custom provider needs one to answer."] = "Видаляє збережений ID моделі. Власному постачальнику він потрібен для відповідей.",
    ["Failed"] = "Помилка",
    ["It answered in {ms} ms."] = "Відповів за {ms} мс.",
    ["It could not be saved."] = "Не вдалося зберегти.",
    ["Model ID: {model}"] = "ID моделі: {model}",
    ["Only https:// works outside this computer and your home network."] = "Поза цим комп’ютером і домашньою мережею працює лише https://.",
    ["Paste API key"] = "Вставити API-ключ",
    ["Paste endpoint URL"] = "Вставити URL",
    ["Paste model ID"] = "Вставити ID моделі",
    ["Sends one tiny message to your endpoint with the saved model ID and key, and shows how it answered. It uses next to nothing of your credits."] = "Надсилає ендпоінту одне коротке повідомлення зі збереженим ID моделі та ключем і показує відповідь. Майже не витрачає кредити.",
    ["Test"] = "Тест",
    ["Test connection"] = "Перевірити зв’язок",
    ["Testing the connection…"] = "Перевірка зв’язку…",
    ["Testing…"] = "Перевірка…",
    ["That is too long."] = "Це занадто довго.",
    ["That was not accepted."] = "Не прийнято.",
    ["The account is out of credits. Add credits with your provider."] = "На рахунку закінчилися кредити. Поповни їх у постачальника.",
    ["The address must start with https:// or http://."] = "Адреса має починатися з https:// або http://.",
    ["The address sends you somewhere else. Use the final address from your provider."] = "Адреса веде в інше місце. Використай кінцеву адресу від постачальника.",
    ["That address is a web page, not the API. For OpenRouter use https://openrouter.ai/api/v1."] = "Ця адреса — вебсторінка, а не API. Для OpenRouter використай https://openrouter.ai/api/v1.",
    ["That address is a web page, not the API. Use the API address from your provider."] = "Ця адреса — вебсторінка, а не API. Використай API-адресу від свого постачальника.",
    ["A model ID is a short name like that, not a web address."] = "ID моделі — це коротка назва на кшталт цих, а не веб-адреса.",
    ["The clipboard does not hold a model ID."] = "У буфері обміну немає ID моделі.",
    ["The clipboard does not hold a web address."] = "У буфері обміну немає веб-адреси.",
    ["The clipboard does not hold an API key."] = "У буфері обміну немає API-ключа.",
    ["The clipboard is empty. Copy it first."] = "Буфер обміну порожній. Спершу скопіюй.",
    ["The connection test failed."] = "Перевірка зв’язку не вдалася.",
    ["The connection works. The endpoint accepted your model and key."] = "Зв’язок працює. Ендпоінт прийняв твою модель і ключ.",
    ["The conversation service is not running, so nothing can be tested. Restart the game."] = "Служба розмов не запущена, тож перевірити нічого не можна. Перезапусти гру.",
    ["The custom provider did not accept your key. Check it in Settings > Conversation provider."] = "Власний ключ не прийнято. Перевір у меню Налаштування > Постачальник розмов.",
    ["The custom provider did not answer. Check its address in Settings, or try again."] = "Власний постачальник не відповів. Перевір адресу в Налаштуваннях або спробуй знову.",
    ["The custom provider does not know that model ID. Check it in Settings."] = "Власний постачальник не знає цього ID моделі. Перевір у Налаштуваннях.",
    ["The custom provider is not set up, so Convai is used. Add its URL and model ID in Settings."] = "Власний постачальник не налаштований: діє Convai. Додай URL і ID моделі в Налаштуваннях.",
    ["The custom provider is rate limiting you. Try again in a moment."] = "Власний постачальник обмежує запити. Спробуй трохи пізніше.",
    ["The custom provider says your account is out of credits. Add credits there, then try again."] = "Власний постачальник каже: на рахунку немає кредитів. Поповни там і спробуй знову.",
    ["The endpoint URL was removed."] = "URL ендпоінта видалено.",
    ["The endpoint answered with no text. Check the model ID."] = "Ендпоінт відповів без тексту. Перевір ID моделі.",
    ["The endpoint did not accept your API key."] = "Ендпоінт не прийняв твій API-ключ.",
    ["The endpoint did not answer. Check its address."] = "Ендпоінт не відповів. Перевір адресу.",
    ["The endpoint does not know that model ID."] = "Ендпоінт не знає цього ID моделі.",
    ["The endpoint is rate limiting you. Try again in a moment."] = "Ендпоінт обмежує запити. Спробуй трохи пізніше.",
    ["The endpoint is rate limiting you. Wait about {seconds} seconds, then try again."] = "Ендпоінт обмежує запити. Зачекай близько {seconds} сек. і спробуй знову.",
    ["The endpoint refused the request. Check the model ID and the address."] = "Ендпоінт відхилив запит. Перевір ID моделі та адресу.",
    ["The endpoint reported an error on its side. Try again in a moment."] = "Ендпоінт повідомив про помилку на своєму боці. Спробуй трохи пізніше.",
    ["The endpoint took too long to answer."] = "Ендпоінт відповідав занадто довго.",
    ["The model ID was removed."] = "ID моделі видалено.",
    ["The provider said: {detail}"] = "Постачальник відповів: {detail}",
    ["This address is not encrypted, which is fine on your own computer or home network."] = "Ця адреса не шифрується, але на твоєму комп’ютері чи в домашній мережі це нормально.",
    ["Use the base URL only: no password, query or #."] = "Вказуй лише базовий URL: без пароля, параметрів запиту та #.",
    ["Waiting for the endpoint to answer…"] = "Очікування відповіді ендпоінта…",
    ["Custom: free daily limit reached"] = "Власний: денний безкоштовний ліміт вичерпано",
    ["New address saved. Paste your API key again for it."] = "Нову адресу збережено. Встав для неї API-ключ ще раз.",
    ["The free daily limit for this model was reached. It resets at {time}."] = "Денний безкоштовний ліміт для цієї моделі вичерпано. Скинеться о {time}.",
    ["The free daily limit for this model was reached. Try again after it resets."] = "Денний безкоштовний ліміт для цієї моделі вичерпано. Спробуй знову після скидання.",
    ["This model spends its reply on thinking. Choose a non-reasoning model in Settings."] = "Ця модель думає замість відповіді. Обери в Налаштуваннях модель без міркувань.",
    ["All"] = "Усі",
    ["Also changed: {names}."] = "Також змінено: {names}.",
    ["Choose any character from the list below. They do not need to be in your current party."] = "Вибери будь-якого персонажа зі списку нижче. Він не обов’язково має бути в твоїй поточній групі.",
    ["Defaults restored."] = "Типові значення відновлено.",
    ["Drag the slider, or press left and right, to turn the page."] = "Перетягни повзунок або натисни ліворуч і праворуч, щоб перегорнути сторінку.",
    ["How loud the mod’s voices are, for companions, characters and V’s typed lines. 100 is the normal level.\n\nAbove 100 the voices get louder, with a limiter so they do not crackle. The game’s own dialogue and sounds do not change.\n\nThe next reply uses it."] = "Наскільки гучно звучать голоси моду: компаньйонів, персонажів і фраз, які ти вводиш за V. 100 — звичайний рівень.\n\nВище 100 голоси звучать гучніше, а лімітер не дає їм хрипіти. Діалоги й звуки самої гри не змінюються.\n\nНаступна відповідь використає значення.",
    ["Not available right now."] = "Наразі недоступно.",
    ["Open Settings to restore its defaults."] = "Відкрий налаштування, щоб відновити типові значення.",
    ["Page"] = "Сторінка",
    ["Show only the models whose name starts with this letter."] = "Показувати лише моделі, назва яких починається з цієї літери.",
    ["Starts with"] = "Починається з",
    ["Open AI NPC Cyberpunk Mod in the Mods list."] = "Відкрий AI NPC Cyberpunk Mod у списку Mods.",
    ["The settings could not be saved. Nothing was changed."] = "Не вдалося зберегти налаштування. Нічого не було змінено.",
    ["You have used today’s {limit} turns, which come back tomorrow. To keep talking now, choose Mistral (with your free key, about 5,000 turns a day) or Local AI (unlimited)."] = "Ти вже використав свої {limit} повідомлень на сьогодні. Вони відновляться завтра. Щоб продовжити зараз, обери Mistral (з безкоштовним ключем, орієнтовно 5 000 повідомлень на день) або Local AI (без ліміту).",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key, and Mistral uses its free plan with your own free key; memory stays on this computer.\n\nWith Mistral, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech is recognized on this computer, so the voice key works."] = "Хто пише відповіді твоїх компаньйонів. Зміна чекатиме, поки жодна розмова не триває.\n\nБезкоштовний тариф Convai не потребує налаштування і дає кращі відповіді. API-ключ Convai використовує твій ключ, а Mistral працює на безкоштовному тарифі з твоїм безкоштовним ключем; пам’ять лишається на цьому комп’ютері.\n\nЗ Mistral, Local AI або Власним хмарний голос Convai замінюється локальним голосом. Мовлення розпізнається на цьому комп’ютері, тож клавіша голосу працює.",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key, and Mistral uses its free plan with your own free key; memory stays on this computer.\n\nWith Mistral, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech recognition for the voice key is not available yet with them, so type your messages."] = "Хто пише відповіді твоїх компаньйонів. Зміна чекатиме, поки жодна розмова не триває.\n\nБезкоштовний тариф Convai не потребує налаштування і дає кращі відповіді. API-ключ Convai використовує твій ключ, а Mistral працює на безкоштовному тарифі з твоїм безкоштовним ключем; пам’ять лишається на цьому комп’ютері.\n\nЗ Mistral, Local AI або Власним хмарний голос Convai замінюється локальним голосом. Розпізнавання мовлення для клавіші голосу поки що недоступне, тож вводь повідомлення текстом.",
    ["Privacy"] = "Конфіденційність",
    ["Send error reports automatically"] = "Автонадсилання звітів про помилки",
    ["Error reports go to the developer automatically. Turn them off in Settings > Privacy."] = "Звіти про помилки сами йдуть розробнику. Вимкнути: Налаштування > Конфіденційність.",
    ["The Companion Manager needs Mod Configuration Menu 0.10.5 or newer, or Native Settings UI"] = "Для «Менеджера компаньйонів» потрібен Mod Configuration Menu 0.10.5+ або Native Settings UI",
    ["Update Mod Configuration Menu to 0.10.5 or newer, or install Native Settings UI"] = "Онови Mod Configuration Menu до 0.10.5+ або встанови Native Settings UI",
    ["Stand up to open the Companion Manager"] = "Встань, щоб відкрити «Менеджер компаньйонів»",
    ["The Companion Manager needs Mod Configuration Menu 0.10.5 or newer, or Native Settings UI {nsui} or newer. Either one is enough. Install one from Nexus Mods, then restart the game."] = "Для «Менеджера компаньйонів» потрібен Mod Configuration Menu 0.10.5 або новіший, або Native Settings UI {nsui} або новіший. Достатньо будь-якого з них. Встанови один із них з Nexus Mods і перезапусти гру.",
    ["Mod Configuration Menu is too old. Update it to 0.10.5 or newer, or install Native Settings UI, then restart the game."] = "Mod Configuration Menu занадто старий. Онови його до 0.10.5 або новішого, або встанови Native Settings UI, і перезапусти гру.",
    ["Previous page"] = "Попередня сторінка",
    ["Next page"] = "Наступна сторінка",
    ["Starts with: {letter}"] = "Починається з: {letter}",
    ["Characters and party"] = "Персонажі та група",
    ["Load a save first"] = "Завантаж збереження",
    ["Inviting characters and managing your party need a loaded game."] = "Запрошувати персонажів і керувати групою можна лише в завантаженій грі.",
    ["Voxtral (recommended)"] = "Voxtral (радимо)",
    ["Defaults"] = "Типово",
    ["Press Confirm to put every setting back to its default."] = "Натисни «Підтвердити», щоб повернути кожен параметр до типового значення.",
    ["Local AI stopped working and was restarted."] = "Local AI перестав працювати і був перезапущений.",
    ["Local AI runs mostly on your processor here, so replies will be slow."] = "Local AI тут працює переважно на процесорі, тому відповіді будуть повільними.",
    ["The yellow border is Windows showing a capture. Choose Mistral or Local AI to stop it."] = "Жовта рамка: Windows робить знімок. Вибери Mistral або Local AI, щоб зупинити.",
    ["Changes this mod’s menus and notices only.\n\nCharacter voices and the language you talk in are separate. The microphone uses this language as a hint for non-English speech."] = "Змінює лише меню та сповіщення цього моду.\n\nГолоси персонажів і мова, якою ти говориш, — окремі речі. Мікрофон використовує цю мову як підказку для мовлення не англійською.",
    ["Voxtral stops speaking; companion replies show as text until a key is saved."] = "Voxtral перестає говорити; відповіді компаньйонів показуються текстом, доки не буде збережено ключ.",
    ["Conversations go back to Convai free tier."] = "Розмови знову працюють через Convai (безкоштовний тариф).",
    ["Deletes the saved key."] = "Видаляє збережений ключ.",
    ["Nothing you use now depends on it."] = "Нічого з того, що ти зараз використовуєш, від цього не залежить.",
    ["The Convai cloud voice cannot use Natural speech, so it was turned off."] = "Хмарний голос Convai не може використовувати Природне мовлення, тому його вимкнено.",
    ["Custom endpoint"] = "Власний ендпоінт",
    ["Speaks up often"] = "Часто озивається",
    ["Speaks up rarely"] = "Рідко озивається",
    ["The address, API key and model ID of your OpenAI-compatible provider, and a connection test. Used when Custom is the Conversation provider."] = "Адреса, API-ключ і ID моделі твого постачальника OpenAI-compatible, а також перевірка зв’язку. Використовується, коли постачальником розмов обрано «Власний».",
    ["V’s voice switches from Voxtral to Pocket."] = "Голос V перемикається з Voxtral на Pocket.",
    ["OmniVoice · needs Omni pack"] = "OmniVoice · треба пакет Omni",
    ["OmniVoice · needs Omni voice"] = "OmniVoice · треба голос Omni",
    ["Requires the Companion voices to be an OmniVoice choice"] = "Потребує, щоб голоси компаньйонів були OmniVoice",
    ["V’s voice switches from OmniVoice to Pocket."] = "Голос V перемикається з OmniVoice на Pocket.",
    ["V’s voice"] = "Голос V",
    ["V (male voice)"] = "V (чоловічий голос)",
    ["V (female voice)"] = "V (жіночий голос)",
    ["Used for V’s typed lines: Pocket, OmniVoice and the Voxtral cloud voice copy it."] = "Використовується для набраних реплік V: Pocket, OmniVoice і хмарний голос Voxtral копіюють його.",
    ["V speaks with the voice of your installed V voice mod, or the shipped V voice."] = "V говорить голосом встановленого моду на голос V або вихідним голосом V.",
    ["Remove the voice clip? V goes back to the voice of your installed V voice mod, or the shipped V voice."] = "Видалити голосовий кліп? V повернеться до голосу встановленого моду на голос V або до вихідного голосу.",
    ["OmniVoice needs an NVIDIA graphics card, and this PC has none that works. Replies show as text. Choose Pocket in Settings to hear voices."] = "OmniVoice потребує відеокарту NVIDIA, а в цьому ПК немає робочої. Відповіді показуються текстом. Щоб чути голоси, вибери Pocket у Налаштуваннях.",
    ["OmniVoice needs an NVIDIA graphics card, and this PC has none that works. Companions are using {voice} instead."] = "OmniVoice потребує відеокарту NVIDIA, а в цьому ПК немає робочої. Компаньйони натомість використовують {voice}.",
    ["OmniVoice needs NVIDIA"] = "OmniVoice потребує NVIDIA",
    ["This PC has no NVIDIA graphics card, which OmniVoice needs. OmniVoice will not start here. Choose Pocket to hear voices."] = "У цьому ПК немає відеокарти NVIDIA, яка потрібна OmniVoice. OmniVoice тут не запуститься. Вибери Pocket, щоб чути голоси.",
    ["{voice} · needs NVIDIA card"] = "{voice} · потрібна карта NVIDIA",
    ["{language} replies show as text: the {language} multilingual pack is missing."] = "Відповіді «{language}» текстом: немає багатомовного пакета «{language}».",
    ["French"] = "французька",
    ["Italian"] = "італійська",
    ["German"] = "німецька",
    ["Spanish"] = "іспанська",
    ["Portuguese"] = "португальська",

    ["OmniVoice needs more graphics memory than is free next to the game. Pocket is used."] = "OmniVoice потребує більше вільної відеопам’яті поруч з грою. Працює Pocket.",
    ["Windows ran out of memory for the voice. A larger paging file or closing other apps helps."] = "Windows бракує пам’яті для голосу. Збільште файл підкачки або закрийте інші програми.",
    ["OmniVoice needs 12 GB"] = "OmniVoice потребує 12 ГБ",
    ["{voice} · needs 12 GB card"] = "{voice} · потрібна карта на 12 ГБ",
    ["The graphics card in this PC has less than the 12 GB OmniVoice needs next to the game. If it cannot start, Pocket is used. Choose Pocket to skip the wait."] = "Відеокарта в цьому ПК має менше 12 ГБ, які потрібні OmniVoice поруч із грою. Якщо він не може запуститися, використовується Pocket. Щоб не чекати, вибери Pocket.",
    ["Forget all memories ({count} characters)"] = "Забути всю пам’ять ({count} персонажів)",
    ["Dynamic info"] = "Жива інформація",
    ["What the game tells each character about this moment. A character mentions it only when it fits the talk.\n\nAn off kind is left out of every conversation provider (Convai, Mistral, Local AI and Custom)."] = "Те, що гра повідомляє кожному персонажу про цей момент. Персонаж згадує це, лише коли це пасує до розмови.\n\nВимкнена категорія не надсилається жодному постачальнику розмов (Convai, Mistral, Local AI і Власний).",
    ["Location"] = "Місце",
    ["Where V is: the district, and V’s apartment or the named place when the game says so.\n\nOff: characters are not told where you are, and the mod stops reading it from the game. The picture Convai gets of what V sees, and an add-on’s own text, are not affected."] = "Де V: район, квартира V або назване місце, коли гра про це повідомляє.\n\nВимкнено: персонажі не дізнаються, де ти, а мод перестає зчитувати це з гри. Образ, який Convai отримує про те, що бачить V, і текст самого доповнення не змінюються.",
    ["Time and weather"] = "Час і погода",
    ["The hour of the day and the weather in Night City.\n\nOff: nobody is told the time or the weather, and the mod stops reading them from the game."] = "Пора доби та погода в Найт-Сіті.\n\nВимкнено: ніхто не дізнається про час чи погоду, а мод перестає зчитувати їх з гри.",
    ["Company and vehicle"] = "Компанія і транспорт",
    ["Who else is with V, whether V is on foot or in a vehicle, and what a companion is doing beside V.\n\nOff: none of this is sent, and the mod stops reading it from the game."] = "Хто ще поруч із V, чи V іде пішки чи їде транспортом і що робить компаньйон поруч із V.\n\nВимкнено: нічого з цього не надсилається, а мод перестає зчитувати це з гри.",
    ["Health, heat and fights"] = "Здоров’я, розшук і бої",
    ["V’s health, the police heat on V, and the last fight V was in.\n\nOff: none of this is sent, and the mod stops reading it from the game."] = "Здоров’я V, поліцейський розшук щодо V і останній бій V.\n\nВимкнено: нічого з цього не надсилається, а мод перестає зчитувати це з гри.",
    ["V’s money"] = "Гроші V",
    ["A rough idea of how many eddies V has: nearly broke, short, comfortable or rich.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "Приблизно скільки едді має V: майже без грошей, мало, достатньо чи багато.\n\nВимкнено: це не надсилається, а мод перестає зчитувати це з гри.",
    ["V’s gear and clothes"] = "Спорядження і одяг V",
    ["What V wears and carries: clothes, weapons and cyberware that can be seen.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "Що V носить і має при собі: одяг, зброю та видиму кіберпротезацію.\n\nВимкнено: це не надсилається, а мод перестає зчитувати це з гри.",
    ["V’s gender and lifepath"] = "Стать і життєвий шлях V",
    ["Whether V is a woman or a man, and V’s lifepath: Nomad, Street Kid or Corpo.\n\nOff: it is not sent with a turn, and the mod stops reading it for that. Your story’s own facts may still reflect your lifepath."] = "Чи V жінка чи чоловік, і життєвий шлях V: Кочівник, Вуличний або Корпорат.\n\nВимкнено: це не надсилається разом із кожною реплікою, а мод перестає зчитувати це з гри для цього. Факти самої історії можуть і далі відображати життєвий шлях V.",
    ["Quest and journal"] = "Завдання і журнал",
    ["V’s tracked quest and its objectives, the jobs V has open and the journal history.\n\nWhat each character knows about your story stays on.\n\nOff: none of this is sent. The mod stops scanning the journal for it, unless Johnny’s remarks are on."] = "Відстежуване завдання V і його цілі, відкриті замовлення V та історія журналу.\n\nТе, що кожен персонаж знає про твою історію, залишається ввімкненим.\n\nВимкнено: нічого з цього не надсилається. Мод перестає сканувати журнал, якщо репліки Джонні не ввімкнено.",
    ["Recent game dialogue"] = "Нещодавні репліки з гри",
    ["The last lines spoken in scenes and V’s chosen replies, so a character can pick up from what was just said.\n\nOff: they are not sent."] = "Останні репліки в сценах і вибрані V відповіді, щоб персонаж міг продовжити з того, що щойно прозвучало.\n\nВимкнено: вони не надсилаються.",
    ["The Runtime is out of date. Get the full install zip."] = "Runtime застарів. Завантаж повний установочний zip.",
    ["The Scripts and Runtime do not match. Update whichever is older. See Help in Settings."] = "Scripts і Runtime не збігаються. Онови старіший. Див. Довідку в Налаштуваннях.",
    ["Scripts {scripts} and Runtime {runtime} do not match: the Runtime is out of date. Extract the full install zip (AI-NPC-LLM-Companions, on Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Scripts {scripts} і Runtime {runtime} не збігаються: Runtime застарів. Розпакуй повний установочний zip (AI-NPC-LLM-Companions, на Nexus Mods) у папку Cyberpunk 2077, потім перезапусти гру.",
    ["Scripts {scripts} and Runtime {runtime} do not match. If the Scripts are older, install the update zip from Nexus Mods. If the Runtime is older, install the full install zip (AI-NPC-LLM-Companions). Extract into the Cyberpunk 2077 folder, then restart the game."] = "Scripts {scripts} і Runtime {runtime} не збігаються. Якщо Scripts старіші, встанови zip-оновлення з Nexus Mods. Якщо старіший Runtime, встанови повний установочний zip (AI-NPC-LLM-Companions). Розпакуй у папку Cyberpunk 2077, потім перезапусти гру.",
    ["The conversation service did not answer the setup check, so its Runtime is probably older than these Scripts. Extract the full install zip (AI-NPC-LLM-Companions, on Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Служба розмов не відповіла на перевірку встановлення, тож її Runtime, імовірно, старіший за ці Scripts. Розпакуй повний установочний zip (AI-NPC-LLM-Companions, на Nexus Mods) у папку Cyberpunk 2077, потім перезапусти гру.",
    ["The Runtime update from {from} to {to} was never applied, so some Runtime files are old. Extract the full install zip (AI-NPC-LLM-Companions, on Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Оновлення Runtime з {from} до {to} так і не було застосовано, тож деякі файли Runtime застарілі. Розпакуй повний установочний zip (AI-NPC-LLM-Companions, на Nexus Mods) у папку Cyberpunk 2077, потім перезапусти гру.",
    ["Runtime files are old. Get the full install zip."] = "Файли Runtime застарілі. Візьми повний ZIP.",
    ["Character unavailable in this game installation."] = "Персонаж недоступний у цій інсталяції гри.",
    ["Message could not be delivered. Please try again."] = "Не вдалося доставити повідомлення. Спробуй ще раз.",
    ["The conversation service could not reply. Please try again."] = "Служба розмов не змогла відповісти. Спробуй ще раз.",
    ["Voice conversation failed. Check your microphone and try again."] = "Голосова розмова не вдалася. Перевір мікрофон і спробуй ще раз.",
    ["{name} is one of your own characters. They need Mistral, Local AI or Custom: choose one under Conversation provider in the settings."] = "{name} — один з твоїх власних персонажів. Для цього персонажа потрібен Mistral, Local AI або Custom: вибери один з них у налаштуваннях, у пункті «Постачальник розмов».",
    ["Companions now and then pause, hesitate, laugh or sigh, as their personality would. It stays rare.\n\nOmniVoice can voice laughs and sighs; the other voices only add pauses.\n\nNot available with Convai’s cloud voice: choosing it turns this off, and turning this on switches the voice to Pocket."] = "Компаньйони час від часу роблять паузу, вагаються, сміються чи зітхають — відповідно до своєї вдачі. Це трапляється рідко.\n\nOmniVoice вміє озвучувати сміх і зітхання; інші голоси лише додають паузи.\n\nНедоступно з хмарним голосом Convai: вибір хмарного голосу вимикає це, а увімкнення переводить голос на Pocket.",
    ["Copy your free key from Mistral first (signing up there needs phone verification). It is read from the clipboard once, checked with Mistral and saved on this computer.\n\nYou can also save it in player-mistral-key.txt in the conversation service folder. Mistral allows about one message a second and about 5,000 turns a day."] = "Спершу скопіюй безкоштовний ключ із Mistral (реєстрація потребує підтвердження телефону). Його один раз зчитують із буфера обміну, перевіряють у Mistral і зберігають на цьому комп’ютері.\n\nТакож його можна зберегти у файлі player-mistral-key.txt у папці служби розмов. Mistral дозволяє приблизно одне повідомлення на секунду та приблизно 5 000 повідомлень на день.",
    ["For testing and bug reports; leave it off for normal play.\n\nShows routine popups, writes a movement trace in the mod’s runtime folder, logs gesture decisions and adds itself to support reports.\n\nFailures, preparation progress and joined notices stay visible when it is off."] = "Для тестів і звітів про помилки; у звичайній грі вимкни.\n\nПоказує службові спливаючі вікна, записує трасу руху в робочу папку моду, веде журнал рішень щодо жестів і додається до звітів підтримки.\n\nХід підготовки, сповіщення про приєднання та помилки лишаються видимими, коли це вимкнено.",
    ["Pocket: the lightest, on your CPU, about 0.2 s to the first word.\n\nOmniVoice: richer, needs a capable GPU and its pack, 1 to 2.5 s.\n\nVoxtral: cloud voices with your Mistral key. The companions’ voice loads no local model; V’s typed lines follow V’s own voice setting.\n\nConvai: its own cloud voice. A voice that cannot run shows replies as text."] = "Pocket: найлегший, працює на процесорі, перше слово приблизно за 0.2 s.\n\nOmniVoice: багатший, потрібні потужна відеокарта та його пакет, 1–2.5 s.\n\nVoxtral: голоси з хмари з твоїм ключем Mistral. Голоси компаньйонів не завантажують локальну модель; репліки, які вводить V, слідують налаштуванню голосу V.\n\nConvai: власний хмарний голос. Голос, який не може працювати, показує відповіді текстом.",
    ["The game’s own named characters, such as Judy, Jackie, Panam and Rogue, answer when you talk to them where they stand, with their own voice and memory.\n\nNothing else about them changes: they do not turn, move, gesture or follow, and stay quiet during scenes, quest conversations, fights and rides.\n\nTakes effect after you reload your save."] = "Власні іменовані персонажі гри, як-от Judy, Jackie, Panam і Rogue, відповідають, коли ти звертаєшся до них там, де вони стоять, своїм голосом і з власною пам’яттю.\n\nІнше в них не змінюється: вони не повертаються, не рухаються, не жестикулюють і не йдуть за тобою. Під час сцен, сюжетних розмов, бійок і поїздок вони мовчать.\n\nНабуває чинності після повторного завантаження збереження.",
    ["Mod Organizer 2. Files the mod creates go to its Overwrite folder; leave them there. Install the full install zip as one mod and update that mod with each new full install zip. Extract multilingual packs into that mod’s folder, not as new mods. Mention Mod Organizer 2 when you send a report."] = "Mod Organizer 2. Файли, які створює мод, потрапляють до його папки Overwrite; залиш їх там. Повний установочний zip встанови одним модом і оновлюй цей мод кожним новим повним установочним zip. Розпакуй багатомовні пакети в папку цього мода, а не як нові моди. Згадай Mod Organizer 2, коли надсилаєш звіт.",
    ["With a mod manager: remove the old Scripts and Runtime mods, then install the full install zip as one mod."] = "З менеджером модів: видали старі моди Scripts і Runtime, а потім встанови повний установочний zip одним модом.",
    ["When something in the mod goes wrong, a short report goes to the developer so it can be fixed.\n\nIt never holds keys, what you or the characters say, memories, audio or your Windows user name.\n\nIt holds the error, versions, your settings, PC details (graphics card, processor, Windows, security software, game drive, screen), installed mod names, setup check, reply timings and the log lines around it."] = "Коли в моді щось іде не так, короткий звіт надсилається розробникові, щоб це виправили.\n\nВін ніколи не містить ключів, того, що кажеш ти чи говорять персонажі, спогадів, аудіо та імені твого користувача Windows.\n\nВін містить помилку, версії, ваші налаштування, дані про ПК (відеокарту, процесор, Windows, захист, диск з грою, екран), назви модів, перевірку встановлення, час відповідей і логи навколо помилки.",
    ["Some Runtime files are from a newer update than this Runtime says. Extract the full install zip (AI-NPC-LLM-Companions, on Nexus Mods) into the Cyberpunk 2077 folder again. Then restart the game."] = "Частина файлів Runtime належить до новішого оновлення, ніж указано для цього Runtime. Розпакуй повний установочний zip (AI-NPC-LLM-Companions, на Nexus Mods) заново в папку Cyberpunk 2077. Потім перезапусти гру.",
    ["Multilingual pack ({code})"] = "Багатомовний пакет ({code})",
    ["PocketTTS model ({code})"] = "Модель PocketTTS ({code})",
    ["Your typed lines are spoken out loud too, in the V voice that matches yours, then the companion answers. V’s line is always waited for, up to about 30 s without audio.\n\nPocket: on your processor, about 0.2 s (its own small model if the companions use another voice). Voxtral: cloud, with your Mistral key. OmniVoice: the companions’ GPU voice, a second more wait."] = "Введені репліки також озвучуються вголос, голосом V, що відповідає твоєму, далі відповідає компаньйон. На репліку V завжди чекаємо, але не довше ніж близько 30 с без звуку.\n\nPocket: на процесорі, приблизно 0.2 s (власна невелика модель, якщо компаньйони використовують інший голос). Voxtral: у хмарі з твоїм ключем Mistral. OmniVoice: GPU-голос компаньйонів, ще секунда очікування.",
    ["Edit characters’ bios, rules and memories, and the prompting for each AI option, in your browser.\n\nWorks with Mistral, Local AI and Custom, not Convai. Changes apply from the next reply."] = "Редагуй у браузері біографії, правила та спогади персонажів, а також промпт для кожного варіанта ШІ.\n\nПрацює з Mistral, Local AI і Власним, не з Convai. Зміни застосовуються з наступної відповіді.",
    ["Edit a character’s bio, speaking style, speaking rules and memories, and the prompting for each AI option, or make a character of your own, in your browser.\n\nWorks with Mistral, Local AI and Custom, not Convai. Changes apply from the next reply."] = "Редагуй у браузері біографію, манеру мовлення, правила мовлення та спогади персонажа, а також промпт для кожного варіанта ШІ, або створи свого персонажа.\n\nПрацює з Mistral, Local AI і Власним, не з Convai. Зміни застосовуються з наступної відповіді.",
    -- Prompting page of the character editor (docs/CHARACTER_EDITOR.md)
    ["Custom: {model} at {host}"] = "Власний: {model} на {host}",
