    ["Advanced parameters (JSON)"] = "Розширені параметри (JSON)",
    ["Extra settings added to every reply, written as a JSON object, for example {example}. Use it for samplers that have no box above. A setting that has its own box above is refused. If a server refuses a setting, it is left out and the reply still comes."] = "Додаткові налаштування, які додаються до кожної відповіді, записані як об’єкт JSON, наприклад {example}. Використовуй їх для семплерів, для яких немає поля вище. Налаштування, яке має власне поле вище, відхиляється. Якщо сервер відхиляє налаштування, його пропущено, а відповідь усе одно надійде.",
    ["Mistral takes only the settings shown here. Top K, Min P and the advanced JSON are for Local AI and Custom models."] = "Mistral приймає лише налаштування, показані тут. Top K, Min P і розширений JSON призначені для моделей Local AI та власних моделей.",
    ["Mistral does not take this setting."] = "Mistral не приймає це налаштування.",
    ["That is not valid JSON."] = "Це не дійсний JSON.",
    ["This must be a JSON object, for example {example}."] = "Має бути об’єкт JSON, наприклад {example}.",
    ["Too many keys. Keep {max} or fewer."] = "Забагато ключів. Залиш {max} або менше.",
    ["“{name}” is not a usable key name. Use letters, digits and underscores."] = "“{name}” не можна використати як назву ключа. Використовуй літери, цифри та символи підкреслення.",
    ["“{name}” has its own setting in this form. Use that instead."] = "“{name}” має власне налаштування в цій формі. Використовуй його натомість.",
    ["Use the Longest reply box for the length of a reply, not “{name}”."] = "Для довжини відповіді використовуй поле «Найдовша відповідь», а не “{name}”.",
    ["“{name}” is set by the mod and cannot be changed here."] = "“{name}” задає мод, і його не можна змінити тут.",
    ["“{name}” needs a number, a text, true or false, or a list of those."] = "“{name}” потребує числа, тексту, true чи false або списку таких значень.",
    ["Longest character description, in characters"] = "Найдовший опис персонажа (у символах)",
    ["Earlier turns kept"] = "Збережено попередніх реплік",
    ["Right-now sentence"] = "Речення «де ти зараз»",
    ["Notes for this turn"] = "Примітки для цієї відповіді",
    ["That prompting option was not found."] = "Цей варіант промпту не знайдено.",
    ["Keep at least one rule."] = "Залиш принаймні одне правило.",
    ["Rule {n} is empty. Write the rule or delete it."] = "Правило {n} порожнє. Напиши правило або видали його.",
    ["Rule {n} is too long. Keep each one under {max} characters."] = "Правило {n} занадто довге. Тримай кожне коротшим за {max} символів.",
    ["The rules are too long together. Keep them under {max} characters in all."] = "Правила разом занадто довгі. Тримай їх у сумі коротшими за {max} символів.",
    ["This text is too long. Keep it under {max} characters."] = "Цей текст занадто довгий. Тримай його коротшим за {max} символів.",
    ["This text cannot be empty."] = "Цей текст не може бути порожнім.",
    ["Use a number from {min} to {max}."] = "Використай число від {min} до {max}.",
    ["Too many stop texts. Keep {max} or fewer."] = "Забагато стоп-текстів. Залиш не більше {max}.",
    ["A stop text is too long. Keep each one under {max} characters."] = "Один стоп-текст занадто довгий. Тримай кожен коротшим за {max} символів.",
    ["{field}: {message}"] = "{field}: {message}",
    ["In use now"] = "Зараз використовується",
    ["How each conversation option is told to answer. Every option has its own prompting. A change counts from the next reply, and nothing needs restarting."] = "Як саме має відповідати кожен варіант розмови. Кожен варіант має власний промпт. Зміни діють із наступної відповіді, перезапуск не потрібен.",
    ["The facts the characters get from the game and a short list of safety filters cannot be edited here. Convai’s prompting lives on Convai’s side."] = "Факти, які персонажі отримують з гри, і короткий перелік фільтрів безпеки тут не редагуються. Промпт Convai зберігається на боці Convai.",
    ["Mistral and Local AI"] = "Mistral і Local AI",
    ["Lite and Standard are the two Local AI model sizes. “Mature on” is used while Mature content is on."] = "Lite і Standard — два розміри моделей Local AI. «Дорослий вміст увімк.» використовується, коли ввімкнено контент для дорослих.",
    ["Your Custom models and APIs"] = "Твої власні моделі та API",
    ["A Custom model appears here once you choose Custom as the conversation provider and set a model."] = "Власна модель з’явиться тут, щойно ти вибереш «Власний» як провайдера розмов і вкажеш модель.",
    ["From {min} to {max}."] = "Від {min} до {max}.",
    ["Shipped: {value}"] = "Стандартне: {value}",
    ["Rule {n}"] = "Правило {n}",
    ["Rule {n}, for a speaker with a reply length of its own"] = "Правило {n}, для мовця з власною довжиною відповіді",
    ["Rule {n}, for Mature content"] = "Правило {n}, для контенту для дорослих",
    ["Move rule {n} up"] = "Перемістити правило {n} вгору",
    ["Move up"] = "Вгору",
    ["Move rule {n} down"] = "Перемістити правило {n} вниз",
    ["Move down"] = "Вниз",
    ["Delete rule {n}"] = "Видалити правило {n}",
    ["Other versions of this rule"] = "Інші варіанти цього правила",
    ["Leave a version empty to use the rule text."] = "Якщо варіант порожній, використовується текст правила.",
    ["For a speaker with a reply length of its own"] = "Для мовця з власною довжиною відповіді",
    ["For Mature content"] = "Для контенту для дорослих",
    ["Shipped: off"] = "Стандартне: вимкнено",
    ["Shipped: the mod’s own limit"] = "Стандартне: власне обмеження моду",
    ["before V’s words"] = "перед словами V",
    ["after V’s words"] = "після слів V",
    ["Repeat the “where you are” sentence right before V’s words"] = "Повторювати речення «де ти зараз» безпосередньо перед словами V",
    ["The notes for this turn go"] = "Примітки для цієї відповіді йдуть",
    ["Output rules"] = "Правила виводу",
    ["The numbered rules the model reads before every reply. Use {name} for the character’s name and {words} for the reply length of a speaker that has one."] = "Пронумеровані правила, які модель читає перед кожною відповіддю. Використовуй {name} для імені персонажа, а {words} — для довжини відповіді мовця, якщо вона в нього є.",
    ["Example replies"] = "Приклади відповідей",
    ["Replies shown to the model after the rules. A small model may copy them word for word, so add none, or keep them short and plain."] = "Відповіді, які показують моделі після правил. Мала модель може скопіювати їх дослівно, тож краще не додавати жодної або зробити їх короткими й простими.",
    ["Add an example reply"] = "Додати приклад відповіді",
    ["An example reply"] = "Приклад відповіді",
    ["Example reply {n}"] = "Приклад відповіді {n}",
    ["Opening line"] = "Початковий рядок",
    ["The first line of the character text. Use {name} for the character’s name."] = "Перший рядок тексту персонажа. Використовуй {name} для імені персонажа.",
    ["The last thing the model reads before it answers. Use {name} for the character’s name and {words} for the reply length. The Mature setting adds its own clause after it."] = "Останнє, що модель читає перед відповіддю. Використовуй {name} для імені персонажа, а {words} — для довжини відповіді. Налаштування для дорослих додає після нього власне речення.",
    ["Section headings"] = "Заголовки розділів",
    ["The headings that mark each part of the prompt. Change the wording, not the order."] = "Заголовки, які позначають кожну частину промпту. Можна змінювати текст, але не порядок.",
    ["Layout"] = "Розташування",
    ["Where some notes go in the prompt."] = "Де в промпті розміщуються деякі примітки.",
    ["Sampling"] = "Семплінг",
    ["How freely the model words its reply. Leave a box empty to use the shipped value."] = "Наскільки вільно модель підбирає слова у відповіді. Залиш поле порожнім, щоб використати стандартне значення.",
    ["Length limits"] = "Обмеження довжини",
    ["Shorten what the model reads, which makes replies faster. The mod’s own limits still apply, so these can only make things shorter."] = "Скорочення того, що читає модель, прискорює відповіді. Власні обмеження моду все одно діють, тож тут можна лише скорочувати.",
    ["Stop texts"] = "Стоп-тексти",
    ["Mature layer"] = "Шар для дорослих",
    ["The crude, forward wording added while Mature content is on. The mod picks the explicit or the suggestive version of a line from what the loaded model allows, so edit the version your model uses. An emptied box leaves that line out. The adults-only line and the hard limits are always added last and cannot be edited."] = "Грубі, прямі формулювання, які додаються, коли ввімкнено Контент для дорослих. Мод обирає відверту або натякаючу версію рядка залежно від того, що дозволяє завантажена модель, тож редагуй версію, яку використовує твоя модель. Порожнє поле прибирає цей рядок. Рядок лише для дорослих і тверді обмеження завжди додаються в кінці й не редагуються.",
    ["Speech line"] = "Рядок мовлення",
    ["Word bank"] = "Словник слів",
    ["Romance line"] = "Романтичний рядок",
    ["Closing clause"] = "Завершальна фраза",
    ["Tone line"] = "Рядок тону",
    ["Partner paragraph: affection and desire"] = "Абзац про партнера: прихильність і бажання",
    ["Partner paragraph: nothing invented"] = "Абзац про партнера: нічого не вигадувати",
    ["{part}, for models that allow explicit sex"] = "{part}, для моделей, які дозволяють відвертий секс",
    ["{part}, for models that keep sex suggestive"] = "{part}, для моделей, які лишають секс натяком",
    ["This option does not get the Mature layer."] = "Цей варіант не отримує шар для дорослих.",
    ["Mature layer and closing line, for models that allow explicit sex"] = "Шар для дорослих і завершальний рядок, для моделей, які дозволяють відвертий секс",
    ["Mature layer and closing line, for models that keep sex suggestive"] = "Шар для дорослих і завершальний рядок, для моделей, які лишають секс натяком",
    ["A reply ends when the model writes one of these. Line breaks count. Up to {max}."] = "Відповідь завершується, щойно модель напише один із них. Переноси рядків враховуються. Не більше {max}.",
    ["Add a stop text"] = "Додати стоп-текст",
    ["A text that ends the reply"] = "Текст, який завершує відповідь",
    ["Stop text {n}"] = "Стоп-текст {n}",
    ["Preview"] = "Попередній перегляд",
    ["The prompt text as the model would read it for a sample character. It follows your edits as you type, before you save."] = "Текст промпту так, як його бачила б модель для зразкового персонажа. Він оновлюється за твоїми змінами, щойно ти друкуєш, ще до збереження.",
    ["Sample character name"] = "Ім’я зразкового персонажа",
    ["A speaker with a reply length of its own"] = "Мовець із власною довжиною відповіді",
    ["Reply length in words"] = "Довжина відповіді у словах",
    ["Mature content is on"] = "Контент для дорослих увімкнено",
    ["The preview waits until the problems in the form are fixed."] = "Попередній перегляд чекає, доки виправлять проблеми у формі.",
    ["No example replies."] = "Прикладів відповідей немає.",
    ["No closing line."] = "Завершального рядка немає.",
    ["Go back to the shipped prompting for {name}? Your changes to this part are removed."] = "Повернути стандартний промпт для {name}? Твої зміни в цій частині буде видалено.",
    ["Go back to the shipped prompting for {name}? All your changes to it are removed."] = "Повернути стандартний промпт для {name}? Усі твої зміни в ньому буде видалено.",
    ["Back to the shipped prompting."] = "Повернути стандартний промпт.",
    ["Prompting"] = "Промпт",
    ["Street reputation"] = "Вулична репутація",
    ["Gangs, the NCPD, corporations and the locals of each district remember what V did: Street Cred, choices in jobs, fights, crimes the police saw and how you treat people. It shapes their greeting, trust and help.\n\nOnly ordinary people, never named or story characters. It changes their words, nothing in the game."] = "Банди, NCPD, корпорації та мешканці кожного району пам’ятають, що зробив V: Street Cred, рішення в замовленнях, бійки, злочини на очах поліції та те, як ти поводишся з людьми. Від цього залежать привітання, довіра й допомога.\n\nЛише звичайні люди, не іменні й не сюжетні персонажі. Змінює їхні слова, нічого в грі.",
    ["NPCs react to threats and commands"] = "NPC реагують на погрози та накази",
    ["Ordinary people you threaten run, cower or fight back, as their kind would: gang members and guards use their fists for an insult and their weapons for a death threat.\n\nThey may also do what you tell them, if they would: get down, stop, or get out of the vehicle.\n\nOnly ordinary people, never named or story characters, and never during scenes, quests or fights."] = "Звичайні люди, яким ти погрожуєш, тікають, зіщулюються від страху або дають відсіч, як властиво їхньому типу: члени банд і охоронці відповідають на образу кулаками, а на погрозу смертю зброєю.\n\nВони також можуть зробити те, що ти їм скажеш, якщо зробили б: лягти на землю, зупинитися або вийти з машини.\n\nЛише звичайні люди, ніколи персонажі з іменем чи з сюжету, і ніколи під час сцен, завдань або боїв.",
    ["Voice language"] = "Мова голосу",
    ["English"] = "англійська",
    ["Automatic"] = "Авто",
    ["Polish"] = "польська",
    ["Russian"] = "російська",
    ["Ukrainian"] = "українська",
    ["Turkish"] = "турецька",
    ["Czech"] = "чеська",
    ["Hungarian"] = "угорська",
    ["Japanese"] = "японська",
    ["Korean"] = "корейська",
    ["Chinese"] = "китайська",
    ["Choose one of the listed reply languages."] = "Оберіть одну з наведених мов відповіді.",
    ["No speech was heard. Hold the talk key while you speak."] = "Мовлення не почуто. Утримуй клавішу голосу, поки говориш.",
    ["Voice activation"] = "Голосова активація",
    ["Voice activation could not open the microphone. Check your Windows input device."] = "Голосовій активації не вдалося відкрити мікрофон. Перевір пристрій введення в Windows.",
    ["Voice input could not reach Convai. Hold the voice key again, or type."] = "Голосовий ввід не зміг з’єднатися з Convai. Утримуй клавішу голосу ще раз або введи текст.",
    ["Talk without a key. While you face a character or a companion is near, the mod listens and answers when you pause for about a second.\n\nNever during the game’s own scenes or choices, or while a character speaks. Nothing leaves your PC unless speech is heard. Headphones work best, but a Bluetooth headset’s microphone drops it to call quality while this listens."] = "Говори, не утримуючи клавішу. Коли ти дивишся на персонажа або поруч супутник, мод слухає і відповідає, коли ти робиш паузу приблизно на секунду.\n\nНіколи під час власних сцен і вибору реплік або поки говорить персонаж. Нічого не виходить із твого ПК, доки не почуто мовлення. Найкраще навушники; мікрофон Bluetooth-гарнітури переводить їх у режим дзвінка під час прослуховування.",
    ["Opening microphone…"] = "Відкриття мікрофона…",
    ["Speak now"] = "Говори зараз",
    ["Type in the search box to find a model by name or record, for example “rita wheeler”. A part of a word is enough."] = "Введи текст у полі пошуку, щоб знайти модель за іменем або записом, наприклад «rita wheeler». Достатньо частини слова.",
    ["Content packs"] = "Пакети контенту",
    ["Add-ons that change how the characters talk."] = "Доповнення, які змінюють те, як говорять персонажі.",
    ["Turns the content pack {name} on or off. A pack changes how the characters talk. Its prompt changes work with Mistral, Local AI and Custom. On Convai its world rules and its own Convai characters apply. A switch counts from the next reply, new names after a restart."] = "Вмикає або вимикає пакет контенту {name}. Пакет змінює те, як говорять персонажі. Його зміни промпта працюють із Mistral, Local AI і Власним. У Convai діють його правила світу та власні персонажі Convai. Перемикач діє з наступної відповіді, нові імена — після перезапуску.",
    ["Content packs add rules after yours. You cannot edit them here: turn a pack off under Settings > Content packs in the game."] = "Пакети контенту додають правила після ваших. Тут їх не можна редагувати: вимкніть пакет у грі в Налаштування > Пакети контенту.",
    ["From the content pack {name}"] = "З пакета контенту {name}",
    ["Content packs that change this prompt: {names}. Your own changes stay on top of theirs, and Reset to default goes back to the pack’s wording."] = "Пакети контенту, які змінюють цей промпт: {names}. Ваші зміни лишаються над їхніми, а Скинути до стандартного повертає формулювання пакета.",
    ["Memory in use"] = "Використовувана пам’ять",
    ["Normal memory"] = "Звичайна пам’ять",
    ["Forget memories clears only the memory shown here. The other memory stays as it is."] = "Забути пам’ять очищає лише пам’ять, показану тут. Інша пам’ять лишається без змін.",
    ["This clears the memory in use: {memory}."] = "Це очищає використовувану пам’ять: {memory}.",
    ["Backspace"] = "Backspace",
    ["Cancelled."] = "Скасовано.",
    ["Caps lock"] = "Caps Lock",
    ["Choose a key or a controller button."] = "Вибери клавішу або кнопку геймпада.",
    ["Choose the keys and controller buttons for talking by voice or text, the group chats and the Companion Manager. They work at once."] = "Вибери клавіші та кнопки геймпада для розмови голосом або текстом, групових чатів і Менеджера компаньйонів. Вони працюють одразу.",
    ["Choose the keys and controller buttons for the mod’s actions. Press Set, then the key or button you want. Esc or B cancels. A change works at once, and the keys you set in Cyber Engine Tweaks keep working. Pick keys the game does not already use."] = "Вибери клавіші та кнопки геймпада для дій мода. Натисни «Задати», потім потрібну клавішу або кнопку. Esc або B скасовує вибір. Зміна працює одразу, а клавіші, призначені в Cyber Engine Tweaks, і далі працюють. Обирай клавіші, яких гра ще не використовує.",
    ["Controller {button}"] = "Геймпад: {button}",
    ["D-pad down"] = "Хрестовина вниз",
    ["D-pad left"] = "Хрестовина вліво",
    ["D-pad right"] = "Хрестовина вправо",
    ["D-pad up"] = "Хрестовина вгору",
    ["Down arrow"] = "Стрілка вниз",
    ["End"] = "End",
    ["Enter"] = "Enter",
    ["Group text chat"] = "Груповий текстовий чат",
    ["Group voice chat"] = "Груповий голосовий чат",
    ["Hold it to talk to the characters around you at once, and let go to send. Facing nobody, you talk to the first member of your party and two others from it."] = "Утримуй, щоб одразу говорити з усіма персонажами поруч, і відпусти, щоб надіслати. Якщо ні на кого не дивишся, говориш із першим членом твоєї команди і ще з двома членами команди.",
    ["Hold it to talk to Johnny, the voice in your head, wherever you face, and let go to send. It needs Johnny in your head turned on in Settings."] = "Утримуй, щоб говорити з Johnny, голосом у твоїй голові, куди б ти не дивився, і відпусти, щоб надіслати. Потрібно, щоб у Налаштуваннях було увімкнено Johnny у твоїй голові.",
    ["Hold the key or button while you speak and let go to send, like the Cyber Engine Tweaks talk key. Facing nobody, you talk to the first member of your party."] = "Утримуй клавішу або кнопку, поки говориш, і відпусти, щоб надіслати, як клавішу розмови в Cyber Engine Tweaks. Якщо ні на кого не дивишся, говориш із першим членом твоєї команди.",
    ["Home"] = "Home",
    ["Insert"] = "Insert",
    ["Key bindings"] = "Призначення клавіш",
    ["Key bindings need Codeware, and this game does not have it. Open Help for what is missing."] = "Для призначення клавіш потрібен Codeware, а його в цій грі немає. Відкрий «Довідку», щоб дізнатися, чого бракує.",
    ["Key or button"] = "Клавіша або кнопка",
    ["Left arrow"] = "Стрілка вліво",
    ["Menu"] = "Меню",
    ["No key was pressed, so nothing changed."] = "Клавішу не натиснули, тож нічого не змінилося.",
    ["Not available"] = "Недоступно",
    ["Not set"] = "Не задано",
    ["Num lock"] = "Num Lock",
    ["Page down"] = "Page Down",
    ["Page up"] = "Page Up",
    ["Pause"] = "Pause",
    ["Press it, then the key or controller button you want. Esc or B cancels. It works at once."] = "Натисни сюди, потім потрібну клавішу або кнопку геймпада. Esc або B скасовує вибір. Працює одразу.",
    ["Press it to open the Companion Manager while you play."] = "Натисни, щоб відкрити Менеджер компаньйонів під час гри.",
    ["Press it to type to the character you face. Facing nobody, you type to the first member of your party."] = "Натисни, щоб написати персонажу, на якого ти дивишся. Якщо ні на кого не дивишся, пишеш першому члену твоєї команди.",
    ["Press it to type to Johnny, the voice in your head, wherever you face. It needs Johnny in your head turned on in Settings."] = "Натисни, щоб писати Johnny, голосу у твоїй голові, куди б ти не дивився. Потрібно, щоб у Налаштуваннях було увімкнено Johnny у твоїй голові.",
    ["Press it to type to the characters around you at once. Facing nobody, you type to the first member of your party and two others from it."] = "Натисни, щоб одразу написати всім персонажам поруч. Якщо ні на кого не дивишся, пишеш першому члену твоєї команди і ще двом членам команди.",
    ["Press the key or controller button for {action}. Esc or B cancels."] = "Натисни клавішу або кнопку геймпада для дії «{action}». Esc або B скасовує вибір.",
    ["Print screen"] = "Print Screen",
    ["Remove the key or button you set here."] = "Видали клавішу або кнопку, призначені тут.",
    ["Right arrow"] = "Стрілка вправо",
    ["Scroll lock"] = "Scroll Lock",
    ["Space"] = "Пробіл",
    ["Tab"] = "Tab",
    ["Talk by text"] = "Розмова текстом",
    ["Talk by voice"] = "Розмова голосом",
    ["Talk to Johnny by text"] = "Розмова з Johnny текстом",
    ["Talk to Johnny by voice"] = "Розмова з Johnny голосом",
    ["That key is already used for another action."] = "Ця клавіша вже призначена для іншої дії.",
    ["The mod’s key bindings could not be loaded. Open Help for what is wrong."] = "Не вдалося завантажити призначення клавіш моду. Відкрий «Довідку», щоб дізнатися, що не так.",
    ["The mod’s scripts did not load, so no key can be set. Open Help for what is wrong."] = "Скрипти моду не завантажилися, тож призначити клавішу не можна. Відкрий «Довідку», щоб дізнатися, що не так.",
    ["Up arrow"] = "Стрілка вгору",
    ["View"] = "Перегляд",
    ["{action} cleared."] = "Призначення «{action}» очищено.",
    ["{action} is set to {key}."] = "«{action}» призначено на {key}.",
    ["{key} is already used for {other}. Choose another."] = "Клавіша {key} вже використовується для «{other}». Обери іншу.",
    ["10 minutes"] = "10 хвилин",
    ["2 minutes"] = "2 хвилини",
    ["5 minutes"] = "5 хвилин",
    ["Cancel this meeting. She is not told."] = "Скасувати зустріч. Їй не скажуть.",
    ["Car"] = "Авто",
    ["Choose how long she waits."] = "Вибери, скільки вона чекатиме.",
    ["Choose how she arrives."] = "Вибери, як вона приїде.",
    ["Choose one of the listed options."] = "Вибери один із варіантів зі списку.",
    ["Choose when she arrives."] = "Вибери, коли вона приїде.",
    ["Companions travel to you when you invite them: they walk or drive in, text you, wait, and remember if you never come.\n\nOff by default."] = "Компаньйони приходять, коли ти їх запрошуєш: пішки або на авто, пишуть, чекають і пам'ятають, якщо ти так і не прийдеш.\n\nЗа замовчуванням вимкнено.",
    ["Fine. Call me when you know what you want."] = "Добре. Дзвони, коли вирішиш, чого хочеш.",
    ["How long she waits"] = "Скільки вона чекає",
    ["How long she waits for you after arriving right now. After a timed arrival she waits as long as the delay you chose. The wait stops while you are in a fight, a scene or a menu."] = "Скільки вона чекатиме на тебе одразу після прибуття. Після прибуття за таймером вона чекає стільки, скільки обрана затримка. Очікування зупиняється під час бою, сцени чи меню.",
    ["How she arrives"] = "Як вона приїжджає",
    ["I waited {minutes} minutes at {place} and you never showed. Forget it."] = "Я чекала {minutes} хвилин у {place}, а ти так і не прийшов. Забий.",
    ["I'm here at {place}. Where are you?"] = "Я на {place}. Ти де?",
    ["Immersive invitations"] = "Занурювальні запрошення",
    ["In 10 minutes"] = "Через 10 хв",
    ["In 2 minutes"] = "Через 2 хв",
    ["In 5 minutes"] = "Через 5 хв",
    ["Invite a companion and she really travels to you: she appears out of sight, walks or drives in, texts you when she is there and waits for you."] = "Запроси компаньйона, і вона справді прийде до тебе: з'явиться поза полем зору, прийде пішки або приїде на авто, напише, коли буде на місці, і чекатиме на тебе.",
    ["Meet at my waypoint when I ask"] = "Зустрітися біля моєї мітки на прохання",
    ["Off: Invite brings a companion to your side at once.\n\nOn: a companion you invite, by the Invite button, the Contacts tab or a text, travels to you and arrives after the time you choose here. She texts you when she is there, waits, and leaves angry (and remembers it) if you never come."] = "Вимкнено: Запросити одразу приводить компаньйона до тебе.\n\nУвімкнено: компаньйон, якого ти запросив кнопкою Запросити, у вкладці Контакти або повідомленням, іде до тебе й прибуває через час, обраний тут. Вона пише, коли на місці, чекає й іде розлючена (і пам'ятає це), якщо ти так і не прийдеш.",
    ["Right now"] = "Зараз",
    ["Right now: she is on her way as soon as she is ready.\n\nIn 2, 5 or 10 minutes: real minutes of play, so she arrives at that time. She then waits as long as that delay."] = "Зараз: вона вирушає, щойно буде готова.\n\nЧерез 2, 5 або 10 хвилин: справжні хвилини гри, тож вона прибуде в цей час. Потім чекає стільки, скільки затримка.",
    ["She texts you"] = "Вона пише тобі",
    ["She texts you when she arrives, when you cancel and when she gives up. Off: no texts (she still remembers being stood up)."] = "Вона пише, коли прибуде, коли ти скасуєш і коли здасться. Вимкнено: без повідомлень (вона все одно пам'ятає, що її покинули).",
    ["Something came up and I can't make it. Sorry."] = "Щось трапилося, не зможу прийти. Вибач.",
    ["Walk"] = "Пішки",
    ["Walk: she appears out of your sight and walks to you.\n\nCar: when a road is near she drives in, stops on the road, gets out and walks the rest. Without a road she walks. The car stays near for a ride, and is removed when she leaves your group or you both go far from it."] = "Пішки: вона з'являється поза полем твого зору й іде до тебе.\n\nАвто: якщо поруч дорога, вона під'їжджає, зупиняється на дорозі, виходить і решту шляху йде пішки. Без дороги йде пішки. Авто лишається поруч для поїздки й зникає, коли вона покидає твою групу або ви обоє відходите від нього.",
    ["When she arrives"] = "Коли вона прибуде",
    ["When you ask her to come to your waypoint and a map pin is set, she goes there and says so. Off: she always comes to where you are."] = "Коли ти просиш її прийти до твоєї мітки і на карті встановлено маркер, вона йде туди й каже про це. Вимкнено: вона завжди приходить туди, де ти.",
    ["Your position cannot be read yet."] = "Твоє місцезнаходження поки що не можна визначити.",
    ["on her way"] = "в дорозі",
    ["the meeting spot"] = "місце зустрічі",
    ["waiting at {place}"] = "чекає на {place}",
    ["{name} is already on the way."] = "{name} вже в дорозі.",
    ["{name} is on her way."] = "{name} в дорозі.",
    ["{name} is on her way. About {minutes} minutes."] = "{name} в дорозі. Приблизно {minutes} хвилин.",
    ["{name} · {state}"] = "{name} · {state}",
    ["{name}: Good to see you. Let us go."] = "{name}: Рада тебе бачити. Поїхали.",
    ["Corpo Plaza"] = "Corpo Plaza",
    ["Heywood Glen"] = "Heywood Glen",
    ["Megabuilding H10"] = "Megabuilding H10",
    ["Move out"] = "Нехай виїде",
    ["That companion is not available."] = "Цей компаньйон недоступний.",
    ["Watson Northside"] = "Watson Northside",
    ["Westbrook Japantown"] = "Westbrook Japantown",
    ["You do not have that apartment."] = "У тебе немає цієї квартири.",
    ["at home"] = "вдома",
    ["out"] = "не вдома",
    ["with you"] = "з тобою",
    ["{count} more housemates"] = "ще {count} співмешканців",
    ["{name} has moved out."] = "{name} більше не живе з тобою.",
    ["{name} is back at home."] = "{name} знову вдома.",
    ["{name} joins you."] = "{name} приєднується до тебе.",
    ["{name} moves into {apartment}."] = "{name} переїжджає до {apartment}.",
    ["{name} now lives in {apartment} and stays in your party until sent home."] = "{name} тепер живе в {apartment} і залишається у вашій групі, поки не піде додому.",
    ["{name} stops living at your place. She stays as she is otherwise."] = "{name} більше не живе у тебе. Решта лишається як є.",
    ["{name} · lives in {apartment} · {state}"] = "{name} · живе в {apartment} · {state}",
    ["Companions change outfits"] = "Компаньйони змінюють одяг",
    ["Your party’s companions change outfits now and then: another look by day and by night, and casual clothes at home, where the character has them.\n\nOnly out of your sight, never in front of you, and only for your party’s own copies, never the game’s own characters. Turning this off keeps what they wear now."] = "Компаньйони з твоєї групи час від часу змінюють одяг: інший образ удень і вночі, а вдома — повсякденний одяг, якщо він є в персонажа.\n\nТільки поза полем твого зору, ніколи на очах у тебе, і лише для власних копій твоєї групи, ніколи для персонажів самої гри. Якщо вимкнути цю опцію, вони залишаться в тому, що мають на собі зараз.",
    ["Choose how often companions speak up."] = "Обери, як часто супутники озиватимуться.",
    ["Companions speak up"] = "Супутники озиваються",
    ["How V is doing according to other mods, when they are installed: Dark Future’s tiredness, hunger, thirst, nerve and addictions, for example. Also what V visibly wears while an Equipment-EX outfit is on, so characters describe the outfit and not the clothes it hides.\n\nOff by default. Off: it is not sent, and nothing is read from those mods."] = "Як почувається V за даними інших модів, якщо вони встановлені: наприклад, втома, голод, спрага, нерви й залежності з Dark Future. А також те, що V помітно носить, поки увімкнено вбрання з Equipment-EX, щоб персонажі описували вбрання, а не одяг, який воно ховає.\n\nЗа замовчуванням вимкнено. Вимкнено: нічого не надсилається, і з цих модів нічого не зчитується.",
    ["How long it has been since V last talked to this character, in the game and in real days: since last night, or days ago. Said only when the gap is long enough to matter, and not again in the same conversation.\n\nOff: it is not sent, and the mod stops reading the game clock for it."] = "Скільки часу минуло від останньої розмови V з цим персонажем, у грі та в реальних днях: від минулої ночі або кілька днів тому. Говориться лише тоді, коли пауза достатньо довга, щоб мати значення, і не повторюється в тій самій розмові.\n\nВимкнено: нічого не надсилається, і мод перестає зчитувати ігровий годинник для цього.",
    ["Music and TV"] = "Музика та TV",
    ["Other mods’ state"] = "Стан інших модів",
    ["Speaks up normally"] = "Озивається зазвичай",
    ["The song playing on the car radio while V rides with the character, or on V’s pocket radio, and what is on a TV near V.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "Пісня, що грає на автомобільному радіо, коли V їде з персонажем, або на кишеньковому радіо V, а також те, що йде на телевізорі поблизу V.\n\nВимкнено: нічого не надсилається, і мод перестає це зчитувати з гри.",
    ["Time since last talk"] = "Час від останньої розмови",
    ["Companions in your party sometimes start talking on their own, at a calm moment or after a scene. With two or more near you, it is often a short chat between up to three of them, and you can join in by talking. Never during fights, scenes, calls or menus.\n\nRarely: about 2 an hour. Normally: about 4. Often (the default): about 6.\n\nWith Johnny speaking up too, the rates add up and they take turns."] = "Супутники інколи самі починають говорити: у спокійний момент або після сцени. Коли поруч двоє або більше, часто виходить коротка розмова між максимум трьома з них, і ти можеш долучитися. Ніколи під час бою, сцен, дзвінків чи в меню.\n\nРідко: близько 2 за годину гри. Зазвичай: близько 4. Часто (за замовчуванням): близько 6.\n\nКоли Johnny теж озивається, обидві частоти додаються, і вони почергово озиваються.",
    ["Johnny Silverhand answers the Talk to Johnny keys, as the voice in V’s head, once the story has him there. Give Talk to Johnny a key on the Key bindings page: none is set by default.\n\nOn: he answers when you talk to him. Rarely: he also speaks up on his own, about 2 an hour. Normally: about 4. Often: about 6.\n\nWith companions speaking up too, the rates add up and they take turns."] = "Johnny Silverhand відповідає на клавіші «Розмова з Johnny» як голос у голові V, коли сюжет його туди ставить. Призначте клавішу «Розмова з Johnny» у «Призначення клавіш»: за замовчуванням жодної.\n\nУвімкнено: відповідає, коли ти з ним говориш. Рідко: сам, близько 2 разів за годину. Зазвичай: близько 4. Часто: близько 6.\n\nКоли супутники теж озиваються, частоти додаються і вони говорять по черзі.",
    ["Choose which live game info the characters are told, such as location, time, weather, company, health, money, gear, quests, music and TV, and other mods’ state.\n\nAll on by default except other mods’ state, which is off. An off kind is not sent to any conversation provider."] = "Обери, яку живу інформацію з гри передавати персонажам, наприклад місце, час, погоду, супутників, здоров’я, гроші, спорядження, завдання, музику та TV і стан інших модів.\n\nЗа замовчуванням усе ввімкнено, крім стану інших модів, він вимкнений. Вимкнений вид не надсилається жодному провайдеру розмов.",
    ["Housemates"] = "Співмешканці",
    ["Housemates talk to each other"] = "Співмешканці розмовляють між собою",
    ["When two or more housemates are home with you, they talk to each other now and then."] = "Коли двоє чи більше співмешканців удома з тобою, вони час від часу розмовляють між собою.",
    ["Characters you tell they can stay at your place move into your apartments and live there."] = "Персонажі, яким ти кажеш, що вони можуть залишитися в тебе, переїжджають до твоїх квартир і живуть там.",
    ["Characters you tell they can stay at your place move into your apartments and live there.\n\nOff by default."] = "Персонажі, яким ти кажеш, що вони можуть залишитися в тебе, переїжджають до твоїх квартир і живуть там.\n\nЗа замовчуванням вимкнено.",
    ["On: characters you tell they can stay at your place move into your apartments and live there, and you can call them along.\n\nOff: nothing of this runs. Turning it off removes them from your apartments but remembers who lived there, so turning it on brings them back."] = "Увімкнено: персонажі, яким ти кажеш, що вони можуть залишитися в тебе, переїжджають до твоїх квартир і живуть там, а ти можеш узяти їх із собою.\n\nВимкнено: нічого з цього не працює. Після вимкнення вони виїжджають із твоїх квартир, але запам’ятовується, хто там жив, тож після ввімкнення вони повертаються.",
    ["OmniVoice Python"] = "OmniVoice Python",
    ["OmniVoice’s code could not load in it"] = "код OmniVoice не міг завантажитися",
    ["PyTorch is not installed in it"] = "PyTorch не встановлений у ньому",
    ["Your own Python (omni-python.txt) is being tested. Open this page again in a minute."] = "Ваш власний Python (omni-python.txt) тестується. Відкрийте цю сторінку знову за хвилину.",
    ["Your own Python (omni-python.txt) is tested when OmniVoice starts or when this page checks again."] = "Ваш власний Python (omni-python.txt) тестується, коли запускається OmniVoice або коли ця сторінка перевіряє знову.",
    ["Your own Python (omni-python.txt) runs OmniVoice with {backend} on {card}. Experimental."] = "Ваш власний Python (omni-python.txt) запускає OmniVoice з {backend} на {card}. Експериментально.",
    ["Your own Python (omni-python.txt) was not used: {reason}. OmniVoice uses the Runtime’s Python, which needs an NVIDIA card."] = "Ваш власний Python (omni-python.txt) не був використаний: {reason}. OmniVoice використовує Python Runtime, якому потрібна карта NVIDIA.",
    ["a test on the graphics card failed"] = "тест на відеокарті не пройдений",
    ["it did not start or did not answer in time"] = "він не запустився або не відповід вчасно",
    ["its PyTorch finds no graphics card (no CUDA or ROCm)"] = "його PyTorch не знайшов відеокарту (без CUDA або ROCm)",
    ["the OmniVoice pack is not installed"] = "пакет OmniVoice не встановлений",
    ["the file does not name a python.exe that exists"] = "файл не вказує на існуючий python.exe",
    ["the module {module} is missing in it"] = "модуль {module} у ньому відсутній",
    ["1 minute"] = "1 хвилина",
    ["2 people"] = "2 людини",
    ["3 people"] = "3 людини",
    ["4 people"] = "4 людини",
    ["Every character who lives at your place moves out at once, from every apartment. Party members who do not live there are not touched. A housemate who is with you stays in your party."] = "Все персонажі, що живуть у тебе, виїжджають одразу, з усіх квартир. Члени групи, що не живуть там, не тронуті. Співмешканець, що з тобою, лишається в твоїй групі.",
    ["Evict"] = "Нехай виїде",
    ["Evict all housemates"] = "Нехай виїдуть усі співмешканці",
    ["Housemates in one chat"] = "Співмешканці в одному чаті",
    ["Housemates moved out: {count}"] = "Співмешканці виїхали: {count}",
    ["How long the housemates stay quiet after a chat before they may start another. The Companions speak up setting still limits how many chats come in an hour."] = "Як довго співмешканці мовчать після чату, перш ніж можуть почати інший. Параметр Супутники озиваються все ще обмежує, скільки чатів приходить за годину.",
    ["How many housemates join one chat when that many are home near each other. They speak one at a time. With fewer at home, the chat is as big as it can be."] = "Скільки співмешканців приєднуються до одного чату, коли стільки людей дома рядом одна з одною. Вони говорять по одному. З менше людей дома чат може бути якомога більшим.",
    ["Move-in apartment"] = "Квартира для переселення",
    ["Nobody lives at your place."] = "У тебе ніхто не живе.",
    ["Pause between chats"] = "Пауза між чатами",
    ["Where a character moves in when you say she can stay but name no apartment and you are not standing in one of yours.\n\nAsk me: she asks which one. Otherwise she takes the apartment you pick here. Only the apartments you own are listed."] = "Де персонаж переселяється, коли ти кажеш, що вона може залишитися, але не називаєш квартиру й не стоїш в одній із своїх.\n\nПитай мене: Вона запитує, яку. Інакше вона бере квартиру, яку ти вибираєш тут. Перелічені лише квартири, що тобі належать.",
    ["Ask me"] = "Питай мене",
    ["Could not start"] = "Не вдалося запустити",
    ["Did not start"] = "Не запустилося",
    ["If the folder is there, the newest log in red4ext/logs says why RED4ext did not load it: an antivirus that removed a file, or a missing Visual C++ runtime."] = "Якщо папка є, найновіший лог у red4ext/logs покаже, чому RED4ext її не завантажив: антивірус видалив файл або бракує Visual C++ runtime.",
    ["Load a save first. A key can be set only while a game is loaded."] = "Спочатку завантаж збереження. Клавішу можна призначити лише тоді, коли гру завантажено.",
    ["No key press reached the mod, so nothing changed. If keys do not arrive from this menu, set the key in Cyber Engine Tweaks’ Bindings: it works the same."] = "Жодне натискання клавіші не дійшло до мода, тож нічого не змінилося. Якщо клавіші не надходять із цього меню, призначте клавішу в розділі призначення клавіш Cyber Engine Tweaks: працює так само.",
    ["Runtime incomplete"] = "Runtime неповний",
    ["Runtime not loaded"] = "Runtime не завантажено",
    ["Service not running ({reason})"] = "Службу не запущено ({reason})",
    ["The Runtime’s plugin is loaded, but the conversation service left no trace in this session. launcher.log in red4ext/plugins/AiNpcCyberpunkCode says why: launcher.ini switched off, Node missing, or Node blocked by a security program. Fix that, then restart the game."] = "Плагін Runtime завантажено, але служба розмов у цій сесії не залишила жодного сліду. launcher.log у red4ext/plugins/AiNpcCyberpunkCode пояснює чому: launcher.ini вимкнено, Node відсутній або Node заблоковано програмою безпеки. Виправ це й перезапусти гру.",
    ["The conversation service cannot see this mod’s folder in the game: a mod manager’s virtual folders, or a folder it may not read. Extract the Runtime straight into the Cyberpunk 2077 folder, or start the game from the mod manager that holds the Runtime."] = "Служба розмов не бачить папку цього мода в грі: віртуальні папки менеджера модів або папку, яку вона не може читати. Розпакуй Runtime безпосередньо в папку Cyberpunk 2077 або запускай гру з менеджера модів, у якому є Runtime.",
    ["The conversation service was started and never reported back. A security program probably stopped it at once, or Node cannot run on this PC. Allow red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe in your security program, then restart the game."] = "Службу розмов запустили, але вона так і не відповіла. Ймовірно, програма безпеки одразу її зупинила, або Node не може працювати на цьому ПК. Дозволь red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe у своїй програмі безпеки, а потім перезапусти гру.",
    ["Windows would not let the game start the conversation service (error {error}). A security program may be blocking node.exe in red4ext/plugins/AiNpcCyberpunkMod/app/node: allow it, then restart the game."] = "Windows не дозволила грі запустити службу розмов (помилка {error}). Програма безпеки може блокувати node.exe у red4ext/plugins/AiNpcCyberpunkMod/app/node: дозволь його, а потім перезапусти гру.",
    ["Add a server address first."] = "Спочатку додайте адресу сервера.",
    ["Asks the server three times who it is and shows whether it is reachable, how long it takes to answer and its version. It sends no speech."] = "Тричі запитує сервер, хто він, і показує, чи він доступний, як швидко відповідає і яка в нього версія. Мовлення не надсилається.",
    ["Connected. The server speaks with {voice}."] = "Підключено. Сервер говорить голосом {voice}.",
    ["Custom voices"] = "Власні голоси",
    ["Deletes the saved server address. Remote OmniVoice needs one to speak."] = "Видаляє збережену адресу сервера. Віддаленому OmniVoice вона потрібна, щоб говорити.",
    ["It answers in {ms} ms."] = "Відповідає за {ms} мс.",
    ["Its voice runs on {device}."] = "Його голос працює на {device}.",
    ["Loading"] = "Завантаження",
    ["Not connected. Replies show as text until the server answers."] = "Не підключено. Відповіді показуються текстом, доки сервер не відповість.",
    ["Nothing answered at that address. Check that the server is running, that the address and port are right and that both PCs are on the same network. A server started with its default only listens on its own PC: start it with the listen address 0.0.0.0."] = "За цією адресою ніхто не відповів. Перевірте, чи запущено сервер, чи правильні адреса й порт і чи обидва ПК в одній мережі. Сервер, запущений із типовими налаштуваннями, слухає лише свій ПК: запустіть його з адресою прослуховування 0.0.0.0.",
    ["Off. OmniVoice runs on this PC."] = "Вимкнено. OmniVoice працює на цьому ПК.",
    ["On, but no server address is saved. OmniVoice cannot speak yet."] = "Увімкнено, але адресу сервера не збережено. OmniVoice ще не може говорити.",
    ["On, but no server address is saved. Pocket is used until you add one."] = "Увімкнено, але адресу сервера не збережено. Доки ви не додасте адресу, використовується Pocket.",
    ["On, but no server address is saved. The server is not used yet."] = "Увімкнено, але адресу сервера не збережено. Сервер ще не використовується.",
    ["On, but a cloud voice is chosen under Companion voices, so the server is not used."] = "Увімкнено, але в «Голоси компаньйонів» вибрано хмарний голос, тому сервер не використовується.",
    ["On. Waiting for the conversation service."] = "Увімкнено. Очікування служби розмов.",
    ["Paste address"] = "Вставити адресу",
    ["Remote OmniVoice"] = "Віддалений OmniVoice",
    ["Render the voices on another PC or graphics card that runs the OmniVoice server, so this PC keeps its frames.\n\nTurn it on, press Apply and add the server address below. The server then speaks for every Pocket or OmniVoice choice under Companion voices; a cloud voice stays as chosen. If it cannot be reached, replies show as text and the mod retries every few seconds."] = "Відтворювати голоси на іншому ПК або відеокарті з сервером OmniVoice, щоб цей ПК зберігав кадри.\n\nУвімкніть, натисніть «Застосувати» й додайте адресу сервера нижче. Сервер далі озвучує кожен вибір Pocket або OmniVoice у «Голоси компаньйонів»; хмарний голос залишається вибраним. Якщо сервер недоступний, відповіді показуються текстом, а мод повторює спробу кожні кілька секунд.",
    ["Render the OmniVoice voices on another PC or graphics card that runs the OmniVoice server."] = "Відтворювати голоси OmniVoice на іншому ПК або відеокарті, на якому працює сервер OmniVoice.",
    ["Render Pocket and OmniVoice voices on another PC or graphics card: the on/off switch, the server address and a connection test. It works whichever of those voices is chosen above."] = "Відтворювати голоси Pocket і OmniVoice на іншому ПК або відеокарті: перемикач увімк./вимк., адреса сервера та перевірка з’єднання. Працює незалежно від того, який із цих голосів вибрано вище.",
    ["Server address"] = "Адреса сервера",
    ["Something answered, but it is not the OmniVoice server. Check the port."] = "Щось відповіло, але це не сервер OmniVoice. Перевірте порт.",
    ["Start the OmniVoice server on the other PC. Its window shows the address to use, for example 192.168.1.20:8765. Copy it, then choose Paste address. It is read from the clipboard once and saved on this computer.\n\nOn the same PC use 127.0.0.1:8765. You can also write address=192.168.1.20:8765 in player-remote-omnivoice.txt in the conversation service folder.\n\nNothing is sent to it until Remote OmniVoice is on and OmniVoice is chosen, or you press Test."] = "Запустіть сервер OmniVoice на іншому ПК. Його вікно покаже адресу для використання, наприклад 192.168.1.20:8765. Скопіюйте її, а потім виберіть «Вставити адресу». Її одноразово зчитають із буфера обміну і збережуть на цьому комп’ютері.\n\nНа тому самому ПК використовуйте 127.0.0.1:8765. Також можна написати address=192.168.1.20:8765 у файлі player-remote-omnivoice.txt у папці служби розмов.\n\nНічого не надсилається, доки Віддалений OmniVoice не увімкнено і не вибрано OmniVoice, або доки ви не натиснете «Перевірити».",
    ["Status"] = "Стан",
    ["The OmniVoice server cannot be reached. Replies show as text until it answers. The mod asks it again every few seconds."] = "Сервер OmniVoice недоступний. Відповіді показуються текстом, доки він не відповість. Мод повторює запит кожні кілька секунд.",
    ["The clipboard does not hold a server address."] = "У буфері обміну немає адреси сервера.",
    ["The clipboard is empty. Copy the address first."] = "Буфер обміну порожній. Спочатку скопіюйте адресу.",
    ["The port must be a number from 1 to 65535."] = "Порт має бути числом від 1 до 65535.",
    ["The server address was removed."] = "Адресу сервера видалено.",
    ["The server answered but could not load its voice. Its window says why."] = "Сервер відповів, але не зміг завантажити свій голос. Його вікно пояснює причину.",
    ["The server answered but is still loading its voice. Try again in a minute."] = "Сервер відповів, але ще завантажує свій голос. Спробуйте за хвилину.",
    ["The server is another version. Use the server folder and the mod from the same release."] = "Сервер іншої версії. Використовуйте папку сервера і мод з одного випуску.",
    ["The server is ready."] = "Сервер готовий.",
    ["The server refused the request."] = "Сервер відхилив запит.",
    ["The server took too long to answer."] = "Сервер відповідав занадто довго.",
    ["Use the address only: no user name, no path, no #."] = "Вкажіть лише адресу: без імені користувача, шляху та #.",
    ["Use the address the server window shows, such as 192.168.1.20:8765, without https://."] = "Вкажіть адресу, яку показує вікно сервера, наприклад 192.168.1.20:8765, без https://.",
    ["Waiting for the server to answer…"] = "Очікування відповіді сервера…",
    ["Whether the server is in use right now. It is checked when a voice is needed and again every few seconds after a failure, never while you play."] = "Чи використовується сервер зараз. Перевіряється, коли потрібен голос, а після збою кожні кілька секунд, але ніколи під час гри.",
    ["Your own character, made in the character editor."] = "Ваш власний персонаж, створений у редакторі персонажів.",
    ["They join as a copy of the model they were made from. They talk with Mistral, Local AI or Custom; with Convai they talk as an ordinary person."] = "Він приєднується як копія моделі, на основі якої створений. Розмовляє через Mistral, Local AI або Власний; з Convai розмовляє як звичайна людина.",
    ["This character needs Mistral, Local AI or Custom to answer."] = "Щоб відповідати, цьому персонажу потрібен Mistral, Local AI або Власний.",
    ["Build for your game"] = "Збірка для вашої гри",
    ["Your game is {game} but the Runtime is the one for game {runtime}. Get the full install zip for game {game} from the mod’s Nexus Mods page (main file for game 2.5, optional file for game 2.31) and extract it into the Cyberpunk 2077 folder over this one, then restart the game."] = "Твоя гра — {game}, але Runtime — для гри {runtime}. Завантаж повний установочний zip для гри {game} зі сторінки моду на Nexus Mods (основний файл для гри 2.5, необов’язковий файл для гри 2.31), розпакуй у папку Cyberpunk 2077 поверх поточних файлів і перезапусти гру.",
    ["Your game is {game} but the Scripts are the build for game {scripts}. Get the update zip for game {game} from the mod’s Nexus Mods page (the update file is for game 2.5, the optional update file for game 2.31) and install it over these, then restart the game."] = "Твоя гра — {game}, але Scripts — збірка для гри {scripts}. Завантаж zip-оновлення для гри {game} зі сторінки моду на Nexus Mods (файл оновлення для гри 2.5, необов’язковий файл оновлення для гри 2.31), встанови поверх поточних і перезапусти гру.",
    ["Your game is {game} but the Scripts and the Runtime are the build for game {scripts}. Get the full install zip for game {game} from the mod’s Nexus Mods page (main file for game 2.5, optional file for game 2.31) and extract it into the Cyberpunk 2077 folder over these, then restart the game."] = "Твоя гра — {game}, але Scripts і Runtime — збірка для гри {scripts}. Завантаж повний установочний zip для гри {game} зі сторінки моду на Nexus Mods (основний файл для гри 2.5, необов’язковий файл для гри 2.31) і розпакуй у папку Cyberpunk 2077 поверх поточних файлів, потім перезапусти гру.",
    ["The Scripts are the build for game {scripts} but the Runtime is the build for game {runtime}, and the game version matches neither. Extract the full install zip made for the same game as yours (from Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Scripts — збірка для гри {scripts}, а Runtime — збірка для гри {runtime}, і версія гри не збігається ні з однією. Розпакуй повний установочний zip для тієї самої гри, що й твоя (зі сторінки на Nexus Mods), у папку Cyberpunk 2077, потім перезапусти гру.",
    ["The Runtime is for game {other}, yours is {game}. Get the full install zip for {game}."] = "Runtime — для гри {other}, у тебе {game}. Візьми повний установчий ZIP для {game}.",
    ["The Scripts are for game {other}, yours is {game}. Get the update zip for {game}."] = "Scripts — для гри {other}, у тебе {game}. Візьми ZIP оновлення для {game}.",
    ["This mod is for game {other}, yours is {game}. Get the full install zip for {game}."] = "Мод для гри {other}, у тебе {game}. Візьми повний ZIP для {game}.",
    ["Scripts are for game {scripts}, Runtime for {runtime}. They must match. See Help in Settings."] = "Scripts — для гри {scripts}, Runtime — для {runtime}. Вони мають збігатися. Див. Довідку.",
    ["Choose one of the listed microphones."] = "Оберіть один із наведених мікрофонів.",
    ["Microphone"] = "Мікрофон",
    ["The microphone you chose in Settings ({chosen}) is not connected, so the Windows default input is used: {name}."] = "Мікрофон, обраний у Налаштуваннях ({chosen}), не підключено, тому використовується стандартний вхід Windows: {name}.",
    ["The microphone you chose in Settings is not connected, so the Windows default input is used."] = "Мікрофон, обраний у Налаштуваннях, не підключено, тому використовується стандартний вхід Windows.",
    ["Windows default"] = "Стандартний у Windows",
    ["not connected"] = "не підключено",
    ["{name}, chosen in Settings > Voices."] = "{name}, обрано в Налаштування > Голоси.",
    ["{name}, the Windows default input. Settings > Voices > Microphone chooses another."] = "{name}, стандартний вхід Windows. Інший обирається в Налаштування > Голоси > Мікрофон.",
    ["Gameplay"] = "Ігровий процес",
    ["Revenge ambushes"] = "Засідки помсти",
    ["A gang you keep killing may rarely send a small squad after you, with a short threat to shout. A long wait follows each one.\n\nNever in a fight, scene, call, vehicle, indoors, safe zone or while wanted. The threats need Talk to ordinary NPCs."] = "Банда, яку ти постійно вбиваєш, рідко може надіслати невеликий загін із короткою погрозою. Після кожного настає довга пауза.\n\nНіколи під час бою, сцени, дзвінка, у транспорті, в приміщенні, в безпечній зоні чи коли тебе розшукують. Погрози потребують «Розмови зі звичайними NPC».",
    ["Speak dialogue choices"] = "Озвучування варіантів реплік",
    ["Say a dialogue choice to pick it: its words, a part of them, or its number (\"two\", \"the last one\"). If nothing fits clearly, nothing is picked. No character answers.\n\nPresses the arrow keys and Enter, so the game must be in front. Needs speech recognition on this PC. Headphones work best."] = "Назви варіант репліки, щоб вибрати його: його слова, частину слів або його номер (\"два\", \"останній\"). Якщо нічого не пасує явно, нічого не вибирається. Жоден персонаж не відповідає.\n\nНатискає стрілки та Enter, тож гра має бути на передньому плані. Потрібне розпізнавання мовлення на цьому ПК. Найкраще працюють навушники.",
    ["No option matched. Say its number."] = "Жоден варіант не підійшов. Назви його номер.",
    ["Two options fit. Say its number."] = "Пасують два варіанти. Назви номер потрібного.",
    ["Speaking a choice needs speech recognition on this PC."] = "Озвучення варіанта потребує розпізнавання мовлення на цьому ПК.",
    ["AMD’s ROCm PyTorch does not support this card yet."] = "ROCm PyTorch від AMD поки що не підтримує цю карту.",
    ["Another setup is already running. Wait for it to finish."] = "Інше налаштування вже виконується. Зачекай, поки воно завершиться.",
    ["Cancelled"] = "Скасовано",
    ["Cancelling…"] = "Скасування…",
    ["Checking your card…"] = "Перевірка твоєї карти…",
    ["Downloading {done} of {total} MB ({percent}%)"] = "Завантаження: {done} з {total} MB ({percent}%)",
    ["Downloading…"] = "Завантаження…",
    ["Experimental. Pocket speaks until it is ready. A local voice never switches to a cloud voice."] = "Експериментально. Pocket говорить, доки OmniVoice не готовий. Локальний голос ніколи не перемикається на хмарний.",
    ["Frees about {disk} GB."] = "Звільняє близько {disk} GB.",
    ["Frees the space it took."] = "Звільняє місце, яке займало.",
    ["Install"] = "Встановити",
    ["Installed"] = "Встановлено",
    ["Installed. OmniVoice uses it when it starts."] = "Встановлено. OmniVoice використовує його під час запуску.",
    ["It is kept in the mod’s data folder on drive C:."] = "Зберігається в папці даних моду на диску C:.",
    ["It runs in the background while you play. The game keeps running and nothing else changes."] = "Працює у фоновому режимі, поки ти граєш. Гра продовжує працювати, і нічого іншого не змінюється.",
    ["It takes about {disk} GB on drive C: in the mod’s data folder."] = "Займає близько {disk} GB на диску C: у папці даних моду.",
    ["MIOpen convolutions (AMD)"] = "Згортки MIOpen (AMD)",
    ["Not available on this PC. It needs an AMD Radeon card and the OmniVoice pack."] = "Недоступно на цьому ПК. Потрібні відеокарта AMD Radeon і пакет OmniVoice.",
    ["OmniVoice for AMD"] = "OmniVoice для AMD",
    ["OmniVoice on AMD: set up first"] = "OmniVoice на AMD: спочатку налаштуй",
    ["OmniVoice then no longer starts on this card until it is set up again."] = "Тоді OmniVoice на цій карті більше не запускається, доки його знову не налаштують.",
    ["On: AMD’s MIOpen runs the convolutions, with MIOPEN_FIND_MODE=2 and MIOPEN_FIND_ENFORCE=1. Off: PyTorch’s own convolutions. Which is faster depends on your card and driver: if voices are slow or stop part-way, try the other one. AMD cards only. OmniVoice restarts with the new choice when it is idle."] = "Увімкнено: MIOpen від AMD виконує згортки, з MIOPEN_FIND_MODE=2 і MIOPEN_FIND_ENFORCE=1. Вимкнено: власні згортки PyTorch. Що швидше, залежить від карти й драйвера: якщо голоси повільні або уриваються на півдорозі, спробуй інший варіант. Лише для карт AMD. OmniVoice перезапуститься з новим вибором, коли буде неактивним.",
    ["Own Python"] = "Власний Python",
    ["Ready"] = "Готово",
    ["Ready. OmniVoice runs on {card} with AMD’s ROCm."] = "Готово. OmniVoice працює на {card} з ROCm від AMD.",
    ["Reinstall"] = "Перевстановити",
    ["Remove AMD setup"] = "Видалити встановлення AMD",
    ["Removing the AMD setup…"] = "Видалення встановлення AMD…",
    ["Run OmniVoice on your AMD Radeon card with AMD’s ROCm: one download, set up from here."] = "Запусти OmniVoice на своїй відеокарті AMD Radeon із ROCm від AMD: одне завантаження, налаштуй звідси.",
    ["Set up OmniVoice for AMD"] = "Налаштувати OmniVoice для AMD",
    ["Starting the AMD setup…"] = "Запуск встановлення AMD…",
    ["Testing it on your card…"] = "Перевірка на твоїй карті…",
    ["The AMD setup was removed."] = "Встановлення AMD видалено.",
    ["The OmniVoice pack is not installed. Install it first."] = "Пакет OmniVoice не встановлено. Спершу встанови його.",
    ["The conversation service is not running. Restart the game."] = "Служба розмов не запущена. Перезапусти гру.",
    ["The download did not finish. Check your connection and try again."] = "Завантаження не завершилось. Перевір з’єднання і спробуй ще раз.",
    ["The download is not ready yet in this version of the mod."] = "Завантаження ще не готове в цій версії моду.",
    ["The downloaded files did not check out. Try again."] = "Завантажені файли не пройшли перевірку. Спробуй ще раз.",
    ["The files could not be unpacked. Try again."] = "Не вдалося розпакувати файли. Спробуй ще раз.",
    ["The setup did not finish. Try again."] = "Встановлення не завершилось. Спробуй ще раз.",
    ["The setup did not pass the test on your card, so OmniVoice cannot use it."] = "Встановлення не пройшло перевірку на твоїй карті, тому OmniVoice не може його використати.",
    ["The setup is installed but did not pass the test on your card. Choose Reinstall."] = "Встановлення є, але не пройшло перевірку на твоїй карті. Вибери «Перевстановити».",
    ["There is not enough free space on drive C:. Free some up and try again."] = "На диску C: недостатньо вільного місця. Звільни трохи і спробуй ще раз.",
    ["This PC has no AMD Radeon card this setup can use."] = "На цьому ПК немає відеокарти AMD Radeon, яку може використати це встановлення.",
    ["Unpacking…"] = "Розпакування…",
    ["Your own Python (omni-python.txt) is used instead. Delete that file to use this setup."] = "Замість цього використовується твій Python (omni-python.txt). Видали цей файл, щоб використати це встановлення.",
    ["your AMD card"] = "твоя карта AMD",
    ["{voice} · AMD: set up first"] = "{voice} · AMD: спочатку налаштуй",
    ["The AMD setup (Settings > Voices > OmniVoice for AMD) runs OmniVoice with ROCm on {card}. Experimental."] = "Налаштування для AMD (Налаштування > Голоси > OmniVoice для AMD) запускає OmniVoice з ROCm на {card}. Експериментально.",
    ["The AMD setup was not used: {reason}. Choose Reinstall in Settings > Voices > OmniVoice for AMD. Until then Pocket speaks."] = "Налаштування для AMD не використано: {reason}. Обери «Перевстановити» в Налаштування > Голоси > OmniVoice для AMD. Доти говорить Pocket.",
    ["Borrow eddies from your characters, lend them eddies and pay each other back, by talking. Each character has money of their own, as their story has it, and decides by how they feel about you. Now and then they ask you for a loan.\n\nEddies change hands as soon as a character agrees, and only with your own characters (party, invited visitors, housemates). The game’s own characters only talk about it. Off by default."] = "Позичайте едді у персонажів, позичайте їм і повертайте одне одному, просто розмовляючи. Кожен має власні гроші й вирішує, виходячи з того, як ставиться до вас. Час від часу вони просять про позику.\n\nЕдді переходять з рук в руки, щойно персонаж погоджується, і лише з вашими персонажами (команда, гості, сусіди). Персонажі гри лише говорять про це. За замовчуванням вимкнено.",
    ["Eddies with characters"] = "Едді з персонажами",
    ["The eddies could not be moved."] = "Едді не вдалося перевести.",
    ["You do not have enough eddies for that."] = "У вас недостатньо едді для цього.",
    ["{name} is no longer with you, so no eddies moved."] = "{name} більше не з вами, тож едді не переводилися.",
    ["Add to favorites"] = "Додати до обраного",
    ["One download of about {size} GB."] = "Одне завантаження, близько {size} GB.",
    ["One download."] = "Одне завантаження.",
    ["Remove from favorites"] = "Видалити з обраного",
    ["Set up OmniVoice on your AMD Radeon card with one download, and choose how it runs."] = "Налаштуй OmniVoice на своїй відеокарті AMD Radeon одним завантаженням і вибери, як він працюватиме.",
    ["That entry cannot be a favorite."] = "Цей запис не можна додати до обраного.",
    ["You have too many favorites. Remove one first."] = "У тебе забагато обраного. Спочатку прибери один запис.",
    ["Your AMD Radeon card ({card}) can run OmniVoice. Set it up in Settings > Voices > OmniVoice for AMD: one download, then it starts by itself."] = "Твоя відеокарта AMD Radeon ({card}) може запускати OmniVoice. Налаштуй його в Налаштування > Голоси > OmniVoice для AMD: одне завантаження, далі він запуститься сам.",
    ["Your AMD Radeon card can run OmniVoice. Set it up in Settings > Voices > OmniVoice for AMD: one download, then it starts by itself. Until then Pocket speaks."] = "Твоя відеокарта AMD Radeon може запускати OmniVoice. Налаштуй його в Налаштування > Голоси > OmniVoice для AMD: одне завантаження, далі він запуститься сам. Доти говорить Pocket.",
    ["Your favorites could not be saved, so they last only until the game closes."] = "Обране не вдалося зберегти, тож воно триватиме лише доти, доки гра не закриється.",
    ["{count} matching characters"] = "Збігів персонажів: {count}",
    ["{name} is no longer a favorite."] = "{name} більше не в обраному.",
    ["A saved party holds {count} characters, so the rest were left out."] = "У збережену групу вміщується {count} персонажів, тому решту не додано.",
    ["Already with you: {names}."] = "Вже з тобою: {names}.",
    ["Another saved party already has that name."] = "Інша збережена група вже має таку назву.",
    ["Could not invite: {names}."] = "Не вдалося запросити: {names}.",
    ["Deletes this saved party. The characters in your party now are not touched."] = "Видаляє цю збережену групу. Персонажі, які зараз у твоїй групі, не зачіпаються.",
